window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II and wenn-sentences · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"If I were you, I would …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Eva's reality – Eva's wishes. Fill in: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"She would like to be taller, though.","why":"*grösser sein*: the wish form of *sein* is **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"She would like to speak Spanish well, though.","why":"An infinitive stands at the end (*sprechen*), so the wish is **würde** + infinitive.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"She would rather work as a tour guide, though.","why":"Infinitive at the end (*arbeiten*) → **würde** + infinitive. *lieber* = rather.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"She would like to have a big flat, though.","why":"*eine Wohnung haben*: the wish form of *haben* is **hätte**. No infinitive is needed.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"What are the people thinking?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Match each picture with a phrase from the box.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"If I didn't have to work, I would be sitting in the garden now.","why":"Picture 1 shows him working, then dreaming in a deck chair. After a *wenn*-clause the main clause starts with the verb (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"If I had a car, I wouldn't have to cycle in the rain.","why":"He is cycling in the rain; a car would spare him that. *müsste* is the Konjunktiv II of *müssen*. *Velo* is Swiss for *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"If the bus weren't late, I would be at the office on time.","why":"A late bus makes her late for work. *wäre* is the Konjunktiv II of *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Rewrite the sentences from a: start with the main clause, then the wenn-clause.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"I wouldn't have to cycle in the rain if I had a car.","why":"Main clause first, then the *wenn*-clause. In the *wenn*-clause the verb (*hätte*) goes to the end.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"I would be at the office on time if the bus weren't late.","why":"Same pattern: main clause, comma, *wenn* … verb at the end (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Fill in the words from the box. Each word is used once; the crossed-out ones are used in the example.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"I would do some things differently if I were the boss in our company.","why":"*machen* at the end → **würde** + infinitive. *Chefin sein* → **wäre**, at the end of the *wenn*-clause.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"If I were Marco, I would definitely do vocational training.","why":"*Marco sein* → **wäre** (like *Wenn ich du wäre …*). The main clause has the infinitive *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"If I could decide freely, I would work in a small company.","why":"*frei entscheiden können* → **könnte** at the end of the *wenn*-clause. Main clause with *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"If we had children, I would only have to work half days.","why":"*Kinder haben* with *wir* → **hätten**. The box leaves **müsste** for the last gap.","source":"k2","check":"*müsste* and *würde* are both correct German in b, c and e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* is just as good). The box only says which three gaps get *würde* and which one gets *müsste*; this key is the most likely split. Ask your teacher which one the book wants."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"I have to hurry because of my work.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Rewrite the answers with weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Because my girlfriend is unpunctual.","why":"*wegen* + noun becomes *weil* + a clause with a verb; the verb (*ist*) goes to the end.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Because the weather is bad.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; after *weil* the verb goes to the end.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Because I have an important appointment.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusative after *haben*); verb at the end.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Fill in: wegen – weshalb – weil – deswegen – denn. A word can be used more than once.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"I can only understand him badly because of his pronunciation.","why":"A noun follows (*seiner Aussprache*, genitive), not a clause → the preposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Someday I'd like to travel to Italy, because I'd like to see the sea.","why":"The verb stays in 2nd place after the gap (*ich möchte*) → **denn**. With *weil* it would go to the end.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"I need to improve my listening, so I watch a lot of films.","why":"The second part is the consequence, and the verb comes right after the gap (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"My children learned German quickly because they are always with Swiss children at kindergarten.","why":"The verb is at the end (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Why do you write the words on little cards?","why":"A question word is needed: **Weshalb** means *warum* (why)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"My sister already speaks almost fluent German, so she can help me learn German.","why":"Consequence, and the verb comes right after the gap (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"At the language course. Fill in: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"I couldn't do the last exercise because I didn't understand it.","why":"The verb is at the end (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"There was nobody at registration, so I went back home.","why":"A new sentence that gives the consequence, with the verb right after the gap (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Because of my good marks, I didn't have to take a test at the start of the course.","why":"A noun phrase follows (*meiner guten Noten*, genitive plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"There is an extra language course because a lot of people have signed up.","why":"The verb is at the end (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Unfortunately I couldn't come to the course yesterday because of my toothache.","why":"A noun phrase follows (*meiner Zahnschmerzen*, genitive plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Who can find the best excuses? Choose one situation and write. The model answers are only one possibility each.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Unfortunately I couldn't tidy the kitchen, because I suddenly had bad back pain. I had to lie down. That's why I watched a film.","why":"Uses *weil* (verb at the end: *hatte*) and *Deswegen* (verb right after it: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Because of the flu, I didn't go to the final exam. I had a high temperature, so I stayed in bed.","why":"Uses *wegen* + genitive (*einer Grippe*) and *deswegen* + verb (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"I'm so sorry! Unfortunately I'm late, because there was an accident on the motorway. Because of the traffic jam I lost two hours.","why":"*denn* keeps the verb in 2nd place (*war*). *wegen des Staus*: genitive of *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (if-sentences, including unreal ones with Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis connector dictionary: wenn (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis connector dictionary: weil (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis connector dictionary: denn (causal, verb stays in 2nd place)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen with genitive)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Growing up with several languages · reading, forum post, crossword, favourite words","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Two or three languages in one family – no problem?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Who says what? Read the three texts and write the name of the person who says each sentence.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“Children want to speak the same language as their friends.” – Janusz","why":"Janusz (text B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“It's good to speak several languages very well, isn't it?” – Yara","why":"Yara (text C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“My children switch between two languages.” – Amira","why":"Amira (text A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* She is the only one who talks about her own children."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"What is right? Read the texts again. Type *richtig* (right) or *falsch* (wrong) after each sentence; in the book you tick only the right ones.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"Amira's children speak Arabic better than German. → right","why":"The family always speaks Arabic at home: *Darum können das die Kinder viel besser.* (Their German here is Swiss German.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"In Amira's family only German is spoken. → wrong","why":"The opposite: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz learned German for six years. → wrong","why":"He was six years old when the family moved (*als ich sechs Jahre alt war*), and he spoke fluent High German after one year."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz and his sister didn't want to speak Polish with their parents. → right","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara speaks three languages fluently. → right","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* German is her fourth language, and she doesn't speak it well yet."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara will soon learn German too. → wrong","why":"She isn't starting soon (*bald*): she has been learning German for two years already (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Writing a forum post. You watched a TV debate on growing up with several languages. In the programme's online forum you find this opinion:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Make notes on the four questions. Short notes are enough, no full sentences. The model notes are one possibility.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Yes: my neighbour's son – Italian with his mother, Swiss German at school","why":"Notes only: a name or person, and which languages where."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"learning two languages without a course, contact with family abroad, advantages at work","why":"Collect two or three advantages; you need them for *Ich finde es sehr gut, dass …* in b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mixing the languages, one language is weaker, a lot of work for the parents","why":"These go into *Es könnte schwierig sein, dass …* and *Auf der anderen Seite …* in b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – children learn two languages well if their parents talk to them a lot","why":"Decide yes or no and give one reason: that becomes *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Now write your opinion on the topic (about 80 words). Use your notes from a and some of the phrases.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"I don't agree with Sandra, because many children learn two languages without problems. My neighbour's son is growing up with Italian and German. He speaks Italian with his mother and Swiss German at school. I think it's very good that he is learning two languages so early. It could be difficult that he sometimes mixes the languages. On the other hand, that is normal for small children. Most important of all is that the parents talk to the child a lot. That's why each parent should speak their own language.","why":"About 85 words, using six of the phrases. *denn* keeps the verb in 2nd place (*lernen*); after *Deswegen* the verb comes next (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Solve the crossword. Each sentence gives the first letter of the missing word. The grid isn't shown here: type the whole word. In the book's grid Ä fills one box.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Our home country is Spain. We come from Spain.","why":"*aus einem Land stammen* = to come from a country (like *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda and Mike don't see each other for six months. That's a long separation.","why":"*die Trennung* = separation, the noun of *sich trennen*. *eine lange* → a feminine noun."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"German and Arabic don't have the same script.","why":"*die Schrift* = script, the letters a language is written in. Arabic uses a different alphabet."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter lives in America now. Since he has lived there, he has changed a lot.","why":"*sich verändern* = to change (as a person). Perfekt: *hat sich verändert*. The Ä fills one box."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"She writes books. She is an author by profession.","why":"*Sie* → the female form with *-in*: *der Autor → die Autorin*. No article after *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"The children don't do their homework. That's why their parents tell them off.","why":"*mit jemandem schimpfen* = to tell someone off. Plural subject *die Eltern* → *schimpfen*. After *Deshalb* the verb comes next."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"She has only been working for a few months. She still has little experience in her job.","why":"*die Erfahrung* = experience. *wenig Erfahrung haben* = to have little experience."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Now we have chaos. Everything is in a mess.","why":"*durcheinander sein* = to be in a mess, mixed up. Written as one word."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"For Ye-Jon the sounds P and F sound the same. She can't tell them apart.","why":"*unterscheiden* = to tell apart. With *kann* the infinitive goes to the end. *tönen* is Swiss for *klingen* (to sound)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"I'm travelling to Greece in the holidays, but unfortunately I can't speak any Greek.","why":"*Griechisch* = the Greek language, with a capital letter. *kein Griechisch können* = not to speak any Greek."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"He only eats vegetables and rice. He eats exclusively vegetables and rice.","why":"*ausschliesslich* = exclusively, nothing but. Swiss spelling with *ss*; Germany writes it with the sharp s."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Solution word (the highlighted row in the grid): mother tongue","why":"Each word gives one letter of the highlighted row: stam**M**en, trenn**U**ng, schrif**T**, (T in the grid), veränd**E**rt, auto**R**in, (S in the grid), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"At home in several languages","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"My most beautiful German word","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Match each photo with a word from the box. The book's coloured dots give the article: blue = der, green = das, red = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (a caramel custard dessert)","why":"Swiss name for crème caramel. *Chöpfli* is Swiss German for 'little head' (*Kopf*). Green dot → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – shooting star","why":"*der Stern* = star; *die Sternschnuppe* = shooting star. Red dot → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – butterfly","why":"Swiss word for *der Schmetterling* (butterfly); Duden marks it *schweizerisch, sonst landschaftlich*. Blue dot → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Why might someone find exactly these words the most beautiful? What do you think? Make notes, then talk about them. The model notes are one possibility.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"so colourful and light, reminds you of summer, funny: the animal isn't a bird at all","why":"Think of what the word makes you see or feel, and how it sounds."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"sweet, reminds you of childhood, sounds funny and typically Swiss","why":"*tönen* = Swiss for *klingen* (to sound)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantic, you can make a wish, sounds soft","why":"Short notes are enough: adjectives and a reason."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"My favourite word","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Which German word and which word in your mother tongue do you like? Why? Write a short text, using the phrases. The model answer is one possibility.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"My favourite German word is “gemütlich” (cosy). When I hear this word, I think of a winter evening with tea, candles and friends. That's why I find it so nice. It sounds soft and warm. In my mother tongue, English, there is no word with exactly this meaning. In English I like the word “sunshine”. For me it is a happy word, because it sounds bright and friendly.","why":"*Wenn …, dann* + verb next (*denke ich*); *Deshalb* + verb next (*finde ich*). Swap in your own mother tongue and words.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Present your text in class. A possible way to start is shown in the model.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Today I'd like to present my favourite word to you. It's the word “gemütlich”. …","why":"Start by naming the word, then read your text from a. *euch* for classmates, *Ihnen* if you speak formally."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis connector dictionary: wenn (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Asking back politely, learning languages, job search · Lesson 4 test","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (official answer key, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (if-sentences, including unreal ones with Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"grammis connector dictionary: weil (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis connector dictionary: denn (causal, verb stays in 2nd place)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"grammis connector dictionary: deshalb (consequence; synonyms daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"grammis connector dictionary: d(a)rum (consequence)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen with genitive)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Excuse me, could you repeat that, please?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Complete each question or sentence with a beginning from the box. Each beginning is used once; the crossed-out one is used in the example.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"What does the expression “es eilig haben” mean?","why":"*Was bedeutet …?* asks for the meaning of a word or expression. (*es eilig haben* = to be in a hurry.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Could you speak more slowly, please?","why":"*Könnten Sie …* (Konjunktiv II) makes the request polite; the infinitive *sprechen* goes to the end.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Sorry, I didn't understand that word.","why":"Perfekt: *habe … verstanden*; *das Wort* stands first for emphasis, so the verb *habe* comes right after it.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Sorry? Could you repeat that, please?","why":"A polite request with *Könnten Sie …*; *wiederholen* (to repeat) goes to the end.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Do you know whether there are integration courses here too?","why":"*ob* introduces an indirect yes/no question, so the verb *gibt* goes to the end.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Excuse me, did I understand that correctly?","why":"A yes/no question in the Perfekt: *habe* first, *verstanden* at the end.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Could you perhaps tell me where the canteen is?","why":"An indirect question with *wo*: the verb *ist* goes to the end. *die Mensa* = a university canteen.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Complete the dialogues. The printed first letters (and a few letters inside the words) are given; type the whole missing words.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Sorry? I didn't understand the last word.","why":"Perfekt: *habe* in position 2 after *Das letzte Wort*, *verstanden* at the end.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Excuse me, it's so loud here. Could you repeat the time, please?","why":"Polite request: *Könnten Sie* … infinitive *wiederholen* at the end. *der Termin* here = the meeting time.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"May I ask you something? – Yes, of course. – Do you know whether there's also a bistro or restaurant on the 14:33 train to Geneva?","why":"*Darf ich Sie etwas fragen?* opens politely; *ob* starts an indirect yes/no question, so *gibt* goes to the end.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Build words from the syllables in the box and complete the sentences. The crossed-out syllables (Men, sa) are used in the example.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"My car is broken again. Could you give me the phone number of your good mechanic once more, please? This time I want to write it down in my address book straight away, so I don't lose it again.","why":"Me-cha-ni-ker (a person who repairs cars) and auf-schrei-ben (infinitive at the end after *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"What does the expression “eine Entscheidung treffen” mean? I've never heard it.","why":"Aus-druck: *der Ausdruck* = expression; *der* and *Den* show it is masculine. (*eine Entscheidung treffen* = to make a decision.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Unfortunately I often forget important German words. I need more time for revision.","why":"Wie-der-ho-lung: *zur* = *zu der*, so a feminine noun follows: *die Wiederholung* (revision, repetition).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Learning foreign languages – but how?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Learning foreign languages – but how?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Who says what? Read the three texts and write the letter of the text (A, B or C) after each sentence.","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"I often listen to other people. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"I learn words on the way to school. → A (Mila)","why":"Mila takes out her word cards on the one-hour train ride to school.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"I'd like to work in England after school. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"I watch a lot of German-language TV. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"I write word cards. → A (Mila)","why":"Mila writes the foreign word on one side of a card and the translation on the other.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Write the second sentence: start with the given word (Deshalb, Darum …) and use the words in brackets. The verb comes right after the starting word.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"That's why she revises new words with word cards.","why":"*Darum* takes position 1, so the conjugated verb *wiederholt* comes next, then the subject *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"For this reason he has a lot of podcasts on his smartphone.","why":"*Aus diesem Grund* fills position 1 like *deshalb*: verb *hat* next, then *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"That's why he wants to speak English well.","why":"*Deswegen* + modal verb *will* in position 2, infinitive *sprechen* at the end.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"So she watches a lot of German-language TV.","why":"*Daher* means the same as *deshalb*; the verb *schaut* comes right after it.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"For this reason she simply listens to the Swiss everywhere, all the time.","why":"*zuhören* is separable: *hört … zu*. The prompt prints *zugehört*, so the Perfekt *hat … zugehört* (as in Danila's text) is also correct.","source":"hueber","check":"The official key gives the present tense (*hört … zu*), although the prompt prints the participle *zugehört*. Both sentences are correct German; ask your teacher which one the book wants."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Lesson 4 test","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complete Arif's text. The book gives the first letter and a few letters inside each word; type the whole word.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… and our mother tongue is Arabic.","why":"*die Muttersprache* = the first language you grow up with."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"That's why I want to improve my German.","why":"The letter pattern (D, e, e) fits *Deswegen*; it gives the consequence, and the verb *möchte* follows right after it.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Of course I won't speak fluent German yet by then.","why":"*fliessend* = fluent(ly). Swiss spelling with *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"I find the script and the pronunciation especially difficult …","why":"*die Aussprache* = pronunciation (*aussprechen* = to pronounce)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… and I don't understand all the expressions yet either.","why":"*der Ausdruck, die Ausdrücke* = expression(s); *alle* needs the plural."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Write unreal if-sentences with *wenn* and the Konjunktiv II (*wäre, hätte, könnte, müsste* or *würde* + infinitive).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"If my English were better, I could help you with the homework.","why":"*sein* → **wäre** at the end of the *wenn*-clause; *können* → **könnte**, then the main clause starts with the verb.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"I would understand you better if you didn't all talk at once.","why":"Main clause first; *würde* + infinitive in both parts. In the *wenn*-clause *würdet* goes to the end.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"I would have more free time if I didn't have to work so much.","why":"*haben* → **hätte**, *müssen* → **müsste** (at the end of the *wenn*-clause).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complete with a word from the box. Each word is used once; the crossed-out one is used in the example (item a's answer).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Why does Costa want to become a mechatronics technician? – Because he's interested in cars.","why":"A question word is needed; **Weshalb** = *warum* (why). The printed answer starts with *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Because of his good knowledge of German, he quickly found an apprenticeship.","why":"A noun phrase follows (*seiner guten Deutschkenntnisse*, genitive plural) → the preposition **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"He's only 17. That's why he still lives with his parents.","why":"A consequence, and the verb comes right after the gap (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Now he's saving money, because he'd like to have his own flat after his training.","why":"A reason, and the verb stays in 2nd place (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"How else can you say it? Complete the second phrase. The book gives some letters; type the whole words.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"I have a question. – May I ask you something?","why":"A polite way to start a question: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Could you say that again, please? – Could you repeat that, please?","why":"*wiederholen* = to repeat = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"What do you mean by …? – What does … mean?","why":"*Was bedeutet …?* asks for the meaning, like *Was meinen Sie mit …?*","check":"The letters in this gap are hard to read in the photo; *Was bedeutet …?* fits them and is the phrase from exercise 13. Ask your teacher if your book shows something else."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Excuse me. / Sorry. – I'm sorry.","why":"*Tut mir leid* = I'm sorry, another way to apologise."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Focus on work: looking for a job","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf is looking for a new job as a hairdresser. He reads a brochure with job-search tips. Read the tips and write the letter of the matching heading (A–E) after each paragraph.","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Paragraph 1 (a list of people you know) → C, Your personal network","why":"Friends, colleagues and former employers are your personal network.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Paragraph 2 (your own job ad on the internet) → A, Online job-seeker ad","why":"*das Stellengesuch* = an ad in which you look for a job; here on an internet portal.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Paragraph 3 (a short application to the company you want) → E, Unsolicited application","why":"You apply to a company that hasn't advertised a job: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Paragraph 4 (applying by phone) → D, Applying by phone","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Paragraph 5 (analysing job ads on the internet) → B, Job ads","why":"*das Stelleninserat* (Swiss) = a job advertisement from a company.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf has decided to take the initiative and has written a job-seeker ad. Read his text and find: who Yusuf is and what he is like, what he can do, and what he is looking for. Write the matching words for each question.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"a committed hairdresser, creative and flexible, 24 years old","why":"Who he is (job, age) and what he is like (adjectives).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"six years of work experience, various further training courses in style consulting","why":"What he offers: experience and training.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"a challenge in which he can learn new things and specialise further","why":"The last sentence: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Place a job-seeker ad on the internet. You are looking for a new job. Make a table with three columns (Who and what am I like? What can I do? What am I looking for?), then write a profile text like Yusuf's in 2. The model answer is one possibility.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Who and what am I like? flexible, a team player, reliable, sociable | What can I do? deal well with customers, good computer skills, fluent German and English | What am I looking for? a part-time job from next month, an international team","why":"A few key words per column are enough; use the phrases from the box.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Are you looking for a reliable saleswoman who is a team player and sociable? I deal well with customers, have good computer skills and speak fluent German and English. I'm looking for a part-time job in an international team from next month.","why":"Same three steps as Yusuf: who you are, what you can do, what you are looking for. *die* in the relative clause refers to *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Grammar","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Wish and reality?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina has to do one thing but would rather do another. Write what she would rather do with *würde* + the words in brackets (with *lieber*, or *gern* in item 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"But she'd rather listen to music.","why":"*würde* in position 2, *lieber* = rather, infinitive *hören* at the end.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"But she'd rather talk to her friend on the phone.","why":"*würde* + *lieber* + infinitive at the end.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"But she'd rather play computer games.","why":"*würde* + *lieber* + infinitive at the end.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"But she would like to read until late at night.","why":"The book prints *gern*: *würde* + *gern* + infinitive (a wish), with *aber* after the verb.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"But she'd rather go dancing.","why":"*würde* + *lieber*; both infinitives *tanzen gehen* at the end.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Rewrite the sentences from a as unreal if-sentences: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"If Nina didn't have to study for a language exam, she would listen to music.","why":"*muss* → **müsste** at the end of the *wenn*-clause; the main clause starts with *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"If Nina didn't have to tidy up her clothes, she would talk to her friend on the phone.","why":"*müsste* + infinitive *aufräumen*: in the *wenn*-clause *müsste* goes last.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"If Nina weren't working on the computer, she would play computer games.","why":"The key accepts *arbeiten würde* or *arbeiten müsste* in the *wenn*-clause."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"If Nina didn't have an appointment very early tomorrow, she would read until late at night.","why":"*hat* → **hätte**, at the end of the *wenn*-clause."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"If Nina weren't spending the evening with her parents, she would go dancing.","why":"*würde* + infinitive in both parts; *verbringen würde* at the end of the *wenn*-clause."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Complete with *darum*, *weil* or *wegen*. Each word is used twice.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Many Germans don't notice Majid's grammar mistakes because he has very good pronunciation.","why":"A reason, and the verb *hat* is at the end → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko didn't pass the exam, so now he wants to take an intensive course.","why":"A consequence, and the verb *will* comes right after the gap → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan wants to work as a doctor in a German hospital, so he needs very good German.","why":"Consequence + verb right after the gap (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla is a manager and can't attend the German course regularly because of her many conferences.","why":"A noun phrase follows (*ihrer vielen Konferenzen*, genitive plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Boris is immediately recognised as Russian because of his accent.","why":"Noun phrase in the genitive (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Anja would like to learn Arabic because she finds the Arabic script so beautiful.","why":"Reason with the verb *findet* at the end → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Vocabulary","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Complete Ferdez's text with the words from the box. Each word is used once; the crossed-out one is used in the example. The worksheet uses German spelling with the sharp s; here Swiss spelling with *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"Macedonian uses the Cyrillic script. That's why writing German wasn't easy for me at first.","why":"*die kyrillische Schrift* = the Cyrillic alphabet."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"I've been living in Bavaria for eight years. By now I speak German fluently, I think.","why":"*fliessend Deutsch sprechen* = to speak German fluently."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"But my colleagues from northern Germany say I have a Bavarian accent!","why":"*einen … Akzent haben* = to have an accent; *einen bayerischen* → masculine noun."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"When I swear in Bavarian, my colleagues fall about laughing.","why":"*schimpfen* = to grumble, to swear; *ich schimpfe* at the end of the *wenn*-clause."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"When I compare German, Macedonian and Albanian with each other, I notice …","why":"*miteinander vergleichen* = to compare with each other; *ich vergleiche* at the end of the *wenn*-clause."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… that you can't translate all words really well into the other language. Today I feel at home in Macedonia and in Germany.","why":"*in eine Sprache übersetzen* = to translate into a language; infinitive before *kann* at the end of the *dass*-clause."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"What does the saying “Lügen haben kurze Beine” (lies have short legs) mean? Type A or B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: The truth always comes out quickly. That's why you shouldn't lie.","why":"A lie can't go far, like someone with short legs: it is soon found out. B is a joke on the literal words."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Which word from the box could replace the underlined word? Write it. Each word is used once; the crossed-out one is used in the example. The underlined words are shown in bold.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"I myself was born in Mainz, though.","why":"*allerdings* = *aber*: it limits what was said before."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"My parents always spoke German with me, so unfortunately I can't speak Farsi.","why":"*deswegen* = *deshalb* (consequence, verb follows right after).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Now I'm taking a language course. I think Farsi is just as difficult as German.","why":"*ebenso … wie* = *genauso … wie* = just as … as."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Especially the script! I'm someone who has to write down all new words.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = to write something down."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"That's hard when you have to do it in a script that you're only gradually learning.","why":"*allmählich* = slowly, step by step, gradually."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"The pronunciation isn't easy either. There's this sound “gh” that I can't pronounce correctly.","why":"*korrekt* = *richtig* = correctly."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"One day it will work – at least I hope so!","why":"*irgendwann* = at some point, one day = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Reading","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Read the answers to the survey “Is learning German important?” and choose the right ending for each sentence. Type the ending (or just its first words).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Anyone who speaks good English still has to learn good German.","why":"Brad, a native English speaker, was told again and again: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"Germans apparently believe that without perfect German you have no professional skills.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena hopes that with the German certificate she'll find a job in Austria.","why":"Alena expects good chances *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"As a Pole, Ewa wants to know German because Germany and Poland share a history.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa thinks it's a pity that not many Germans are interested in Polish.","why":"Ewa wishes that more Germans were interested in Polish."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha learned German from her husband.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"She has problems because she doesn't understand the teachers well enough.","why":"With the class teacher and at parents' evenings she has *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Good German is expected for the work permit.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah wants to know German well because he lives in Germany.","why":"He wants to know the language *des Landes …, in dem ich lebe*; his German is already enough for the patients."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha is learning German because of her children.","why":"Her children complained that her German was so bad, and now they help her learn."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Speaking","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Which reply fits best? Write the number of the reply (1–6) after each sentence. (Exercise 6 on this page is a listening task and is left out.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"My name is Kranitzky-Krampe. → 5 Sorry, what was your name?","why":"A long, unusual name: you ask again."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"You can also say “Klamotten” for clothes. → 4 I've never heard that word.","why":"A new (colloquial) word: *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"What does this word mean? → 1 I'm afraid I don't know either.","why":"A reply to a question you can't answer."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"I was really lucky there. → 6 Did I get that right: you were lucky?","why":"*Schwein haben* (colloquial) = to be lucky; you check that you understood."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Could you speak more slowly, please? → 3 Okay, I'll try.","why":"A reply to a request."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Write the indirect questions with the words in brackets. In an indirect question the verb goes to the end.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Can you tell me where I have to take the rubbish?","why":"*wohin* starts the indirect question; the conjugated verb *muss* goes to the end."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Can you please tell me where you're in pain?","why":"The doctor asks: *wo* + subject + verb at the end (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Do you happen to know whether the train goes to Berlin?","why":"A yes/no question becomes indirect with *ob*; the verb *fährt* goes to the end."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Writing","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Choose a language you would like to learn and write a message to the language school: which language, when and how often a week you have time, which course dates/times they offer, the course fees and length, ask for a reply, and use a suitable greeting and closing. The model answer follows the official key.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Dear Sir or Madam, I would like to learn Modern Greek. I have time from Monday to Thursday in the evenings and could come twice a week. Please let me know at what times you offer a Modern Greek course. I would also need to know how much the course costs and how long it lasts. I would ask you for a short reply. Kind regards …","why":"Formal letter: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. The questions are indirect (*zu welchen Zeiten …, wie viel …, wie lange …*): verb at the end."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Infinitive with zu, the application letter, small talk about work · Lesson 5 test","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (official answer key, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (modal verbs without zu; brauchen with zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (infinitive clauses with zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu between the particle and the verb: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (dass clause or zu + infinitive)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (Präposition, with the genitive)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (prepositions and the cases they take)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Finally start writing applications!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"I'm afraid I haven't got time …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Complete each sentence with a verb from the box. Each one is used once; the crossed-out one is used in the example.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"Please don't forget to switch off the cooker.","why":"*ausschalten* is separable, so *zu* goes between the particle and the verb: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"I'm afraid of being alone at night.","why":"*Angst haben* + *zu* + infinitive; *sein* is a simple verb, so *zu* stands before it.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"No, it isn't too stressful to help out in a club.","why":"*Es ist* + adjective + *zu* + infinitive. *mitarbeiten* is separable: *mit**zu**arbeiten*. (The first *zu* here means \"too\".)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"I'm afraid I haven't got time to explain the way to you.","why":"*keine Zeit haben* + *zu* + infinitive. *erklären* is not separable (*er-* is an inseparable prefix), so *zu* stands before it.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"I don't feel like coming along to training today.","why":"*keine Lust haben* + *zu* + infinitive; *mitkommen* is separable: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Which expressions are followed by *zu*? Type the expression (the verb or verb + noun/adjective) that triggers *zu* in each sentence from a.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"Please don't forget to switch off the cooker. → forget","why":"The verb *vergessen* (here *Vergesst*) is followed by *zu* + infinitive.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"I'm afraid of being alone at night. → be afraid","why":"*haben* + noun (*Angst, Lust, Zeit, Interesse*) is followed by *zu* + infinitive.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"No, it isn't too stressful to help out in a club. → is (not too) stressful","why":"*Es ist* + adjective is followed by *zu* + infinitive.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"I'm afraid I haven't got time to explain the way to you. → have (no) time","why":"*Zeit haben* (here *keine Zeit*) is followed by *zu* + infinitive.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"I don't feel like coming along to training today. → feel like it (not)","why":"*Lust haben* (here *keine Lust*) is followed by *zu* + infinitive.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Where does *zu* go? The table has three columns: the start of the sentence, the middle part, then the verb with *zu*. Put the sentences from a with a separable verb (2, 4, 6) into it and type the last column. The verb's parts are in brackets.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"Please don't forget | the cooker | to switch off.","why":"Separable verb: *zu* goes between *aus* and *schalten*, and it is all one word.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"No, it isn't too stressful | in a club | to help out.","why":"Separable verb: *mit* + *zu* + *arbeiten*, written as one word.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"I don't feel like it today | to training | to come along.","why":"Separable verb: *mit* + *zu* + *kommen*, written as one word.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"What is right? Type *zu* if the sentence needs *zu*, or *–* (a dash) if it needs nothing.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Wouldn't you also like to work in your dream job?","why":"After a modal verb (*möchten*) the infinitive never takes *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"I could well imagine learning a trade.","why":"*sich vorstellen können* introduces a second clause after the comma, with *zu* + infinitive. *könnte* only belongs to *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"With training as a craftsman you can find a good job.","why":"Modal verb *kann* + infinitive without *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Could you help me choose a career?","why":"*Könnten* is a modal verb (Konjunktiv II of *können*): no *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"It's quite stressful to find out about the career options.","why":"*Es ist* + adjective (*stressig*) + *zu* + infinitive.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Complete with *zu*, or type *–* (a dash) where nothing is missing.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"We mustn't forget the boss's birthday!","why":"Modal verb *dürfen* + infinitive without *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"It isn't easy to find a position in your dream job.","why":"*Es ist nicht leicht* + *zu* + infinitive.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"I would most like to work in a team.","why":"*würde* + infinitive (Konjunktiv II) works like a modal verb: no *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Have you got a moment to help me with my application?","why":"*Zeit haben* + *zu* + infinitive.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Can you imagine an apprenticeship in an office?","why":"*Kannst* is a modal verb, so nothing goes in: *vorstellen* is written as one word.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Finally start writing applications!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Write sentences about your working life: combine an expression from the left box with an activity from the right box. Crossed-out words are used in the example. The model answer is one possibility.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"In my working life I don't want to do the same thing all the time. I hope to work with nice colleagues. I enjoy learning new things. I can work very well on my own. It's tiring to have little free time. I would like to travel round the world for six months.","why":"After *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* use *zu* + infinitive (separable verbs: *zusammen**zu**arbeiten*). After *möchten, können, würde … gern* no *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Match each statement with a verb from the box and write a sentence with *zu* + infinitive. The crossed-out verb is used in the example.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"I promise to pick you up tomorrow.","why":"\"Definitely\" = a promise: *versprechen*. *abholen* is separable: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"I plan to find an interesting job.","why":"A plan = *vorhaben*: *Ich habe vor, … zu finden.* The particle *vor* goes to the end of the main clause.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"I can imagine learning a trade.","why":"\"Why not?\" = you can imagine it: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"At the end of the month I'm stopping work as a nurse.","why":"\"Only until the end of the month\" = stopping: *aufhören*, with *auf* at the end of the main clause before the comma.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Find nine more words in the letter grid and put them into the job ads A–C. The circled words (*Bewerbung, Tätigkeit*) are the examples. Type each word in the form the sentence needs (capital letter for nouns).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"We are looking for support for our patient transport service, 15 hours a week.","why":"*die Unterstützung* = support, help; here it means a person who helps.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"The requirement for the job is: a category B driving licence","why":"*die Voraussetzung* = requirement, precondition. *der Führerausweis* is the Swiss word for driving licence.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ knowledge of first aid","why":"*Kenntnisse in* + dative = knowledge of / skills in.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"What awaits you: interesting tasks, further training opportunities, a pleasant working atmosphere","why":"*Es erwarten Sie …* = \"… await you\"; *es* only fills position 1, the verb agrees with the plural subject that follows.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ interesting tasks","why":"*die Aufgabe, die Aufgaben* = task(s); *interessante* shows a plural.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Experience in retail and sales an advantage.","why":"*der Handel* = trade, retail; *im* = *in dem*. *von Vorteil* = an advantage.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"If you have questions, contact Ms Kleinert in writing or by phone.","why":"*schriftlich oder telefonisch* = in writing or by phone.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Do you like working with wood?","why":"*sich beschäftigen mit* = to occupy yourself with; *du beschäftigst dich*. It starts the yes/no question, so it has a capital letter.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Send your application documents today to: Clemens Meier","why":"*die Bewerbungsunterlagen* (plural) = CV, certificates and letter together.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Finally start writing applications!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Complete with the right form of *brauchen* or *müssen*. Tip: *brauchen* goes with *zu* + infinitive and a negative or *nur*; *müssen* never takes *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"Your report is so good. You really don't need to worry about a job.","why":"Negative (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"If she only works part-time, she doesn't have to sit at the computer all day.","why":"The infinitive *sitzen* has no *zu*, so the verb is *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"If we want to travel abroad for three months, we have to save a lot of money now.","why":"No *zu* and no negative: an obligation, so *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"My dream job. Write sentences with *brauchen … zu* + infinitive (= not have to / only have to).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"I don't have to take on any boring tasks.","why":"*brauchen* in position 2, *zu übernehmen* at the end. *übernehmen* is not separable here, so *zu* stands before it.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"I don't have to work overtime.","why":"*keine* + *brauchen … zu* = no obligation.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"I only have to work when I feel like it.","why":"*nur brauchen … zu* = only have to. *zu arbeiten* closes the main clause before the *wenn*-clause.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"I don't have to work with unfriendly colleagues.","why":"*zusammenarbeiten* is separable: *zusammen**zu**arbeiten*, one word.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"An application letter","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Read the parts of the letter and put them in the right order: type the number (1–8) of each part. The parts are lettered A–H here in the order the book prints them; B is the example.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"I find it easy to learn new things. I also enjoy advising customers. That is why I would like to work for you as a salesperson. → 5","why":"Why you want the job comes after your experience (4) and before the closing request (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Kind regards / Tibor Kelemen → 7","why":"The closing greeting and your name come after the last sentence.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"I read your advertisement with great interest and am applying for the vacancy as an e-bike salesperson. → 3","why":"The first sentence after the greeting says which job you are applying for.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"I would be pleased to be invited to an interview. → 6","why":"The standard last sentence of an application letter.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Enclosures: CV, references → 8","why":"*Beilagen* (enclosures) come at the very end, below the name.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Dear Sir or Madam → 2","why":"The greeting follows the subject line. In Switzerland there is no comma after it.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"As you can see from my documents, after finishing secondary school I trained as a bicycle mechanic with the company “Velo-XL”. Then I worked for two years as an employee in a bike shop and also gained my first experience in sales. → 4","why":"Your training and experience come after the opening sentence.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Finally start writing applications!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Complete the application letter. You will find help in a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Dear Ms Zerlich","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: the ending follows the person.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"I read your job advertisement with great interest and am applying for the position as a physiotherapist.","why":"Fixed opening phrase from a; it takes position 1, so the verb *habe* follows.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"As you can see from my documents, after training as a physiotherapist I worked in a hospital in Lodz, Poland, for four years.","why":"*etwas (Dativ) entnehmen* = to see from something: *meinen Unterlagen* is dative plural.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Then I worked for two years at the Kunz & Rosenthal practice. There I was also able to gain experience in sports medicine.","why":"*Erfahrungen sammeln* = to gain experience.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"My mother tongue is Polish. But I also speak very good German and English.","why":"*die Muttersprache* = first language; *meine* because it is feminine.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"The job in a care home is something completely new for me. I really enjoy learning new things. I also like looking after other people and look forward to contact with the residents.","why":"*Es macht mir Freude, … zu* + infinitive, as in a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"I would be pleased to be invited to an interview.","why":"Fixed closing sentence: *eine Einladung zu* + dative.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Kind regards, Alina Jankowska","why":"Closing greeting; Swiss spelling *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Choose one of the three job ads from Zirkus Tortellini and write an application letter. Use the parts from a and b. The model answer is one possibility.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Application as an acrobat / Dear Mr Tortellini / I read your job advertisement with great interest and am applying for the position as an acrobat in your circus. As you can see from my documents, I trained as a dancer. Then I danced at a theatre in Bern for three years and gained my first experience on stage there. I really enjoy performing in front of an audience. I can well imagine travelling through Switzerland with your circus. I would be pleased to be invited to an interview. / Kind regards / Lara Steiner / Enclosures: CV, reference","why":"Same eight parts as in a; each one answers a point of the ad (training as a dancer, first experience at a theatre). *auf**zu**treten*: *auftreten* is separable.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"During his last school year …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Complete with *während* (during), *innerhalb* (within) or *ausserhalb* (outside), plus the word in brackets in the right form. All three take the genitive.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Thank you for your application. You will receive our answer within a few weeks.","why":"A time limit = *innerhalb*; genitive plural without article: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"You are calling outside our business hours. These are from …","why":"Outside a time span = *ausserhalb*; genitive plural *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"You are welcome to have a coffee while you wait.","why":"At the same time as = *während*; genitive feminine *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"The company wants to improve its results by 20% within the next two years.","why":"A time limit = *innerhalb*; genitive plural *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Complete the interview with the time prepositions from the box. Each one is used once; *während* is in the box twice. The crossed-out *von … an* is used in the example.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"Technology has always interested me. Even during my school years I worked for an electrician.","why":"*während* + genitive (*meiner Schulzeit*) = during.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Straight after school I did an internship at a big energy company.","why":"*nach* + dative (*der Schule*) = after.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"But already during the first year you get to know the most important things.","why":"*während* + genitive *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Before the final exam I still have to learn a lot, though.","why":"*vor* + dative (*der Abschlussprüfung*) = before; capital letter at the start of the sentence.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"From morning until the end of the working day I'm out and about on our company's site, repairing equipment.","why":"*von … bis* = from … until; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"What experiences have you had as a woman in your work?","why":"*bei* + dative (*deiner Arbeit*) = in the course of, at.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Only positive ones! My colleagues and I often meet in the evenings, so outside working hours.","why":"*ausserhalb* + genitive (*der Arbeitszeit*) = outside.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Exam practice: read the e-mail and fill gaps 1–6. Which option (a, b or c) fits best? Type the word (or its letter).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Thank you for your application as a car mechatronics technician.","why":"*Vielen Dank für* + accusative.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"We are pleased about your interest in our company …","why":"*Interesse an* + dative = interest in; *Ihr* fits the neuter *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Please let us know within the next few days …","why":"A time limit with genitive (*der nächsten Tage*) = *innerhalb*. *bis* would need *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"… whether you can come to this appointment.","why":"An indirect yes/no question needs *ob* (whether).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Please also bring the following documents: your vocational school certificate in the original and your B2 certificate.","why":"A certificate and a diploma are *Dokumente*; *Zeugnisse* would not cover the B2 certificate as well, and *Sachen* is too vague for a formal letter.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"We are happy to answer any questions and give you further information.","why":"Fixed phrase: *jemandem zur Verfügung stehen* = to be available to someone.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"During his last school year …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Match each question or remark from a job interview with the answer (1–7). Type the number. (Exercise 13 is a listening task and is left out.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Please tell us something about yourself. → 7 Well, I'm a construction machinery mechanic and I'm doing my category BE driving licence.","why":"You introduce yourself: your job and what you are doing now.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"What tasks did you have with your last employer? → 1 I was responsible for checking household, garden and leisure goods.","why":"*zuständig sein für* = to be responsible for (your tasks).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Do you have any other skills? → 6 Yes, I speak three languages.","why":"A yes/no question about skills: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Can you tell me more about your computer skills? → 2 I know the usual programs and did further training in warehouse databases last year.","why":"*beherrschen* = to master; *sich weiterbilden* = to do further training.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Do you have any more questions? → 3 Yes, I would like to know how big the warehouse here is.","why":"An indirect question: *wie gross das Lager hier ist* (verb at the end).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Thank you for coming, Mr Trantow. → 4 Thank you too.","why":"You return the thanks: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"I can do this! Complete the sentences with information about yourself. The model answers are one possibility.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Even during my school years I had a part-time job in a café.","why":"*während* + genitive; Perfekt with the participle at the end.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"I was responsible for the accounts in a small office.","why":"*zuständig für* + accusative.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"I am proficient in Excel and the usual office programs.","why":"*beherrschen* + accusative = to master a skill or language.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"I also have a very good knowledge of English and Italian.","why":"*Kenntnisse in* + dative.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"I find it easy to work in a team and to approach new customers.","why":"*Es fällt mir leicht* + *zu* + infinitive; *zugehen* is separable: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Careers advice","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"What is right? Read the texts. Type *richtig* (right) or *falsch* (wrong) after each sentence; in the book you tick only the right ones.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline doesn't feel like studying at university. → right","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"She finds it difficult to plan or organise things. → wrong","why":"The opposite: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"Next week she wants to find out about commercial training. → right","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, about a commercial job.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos planned to work in technology after school. → right","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"At first he found it difficult to combine his areas of interest. → right","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"He expected to enjoy the apprenticeship as a landscape architecture draughtsman. → wrong","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = he did not expect it.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Write a sentence with *zu* + infinitive for each prompt (a–e). Then find the advice (1–5) that fits; the solution shows its number.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"I don't find it hard to get up early. → 4 How about a job as a baker?","why":"*Ich finde es* + adjective + *zu* + infinitive; *aufstehen* is separable: *auf**zu**stehen*. Bakers start very early.","source":"g4069","check":"The official key writes *Es fällt mir nicht schwer, früh aufzustehen*, which means the same; the prompt *es nicht schwer finden* gives *Ich finde es nicht schwer, …*. Both are correct."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"I like the idea of being on the move a lot. → 1 You could become a bus driver.","why":"*Lust haben* + *zu* + infinitive.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"I enjoy cooking for other people. → 5 If I were you, I would become a cook.","why":"*Es macht mir Freude* + *zu* + infinitive.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"I'm interested in developing new things. → 3 Hmm, difficult. Maybe a fashion designer?","why":"*Interesse haben (daran)* + *zu* + infinitive; *daran* points forward to the *zu*-clause.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Words with -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Make nouns ending in *-ung* from the verbs, with the article. (Parts b–d are listening tasks and are left out.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"to experience → experience","why":"Verb stem + *-ung*; nouns in *-ung* are always feminine: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"to be responsible for → responsibility","why":"Stem *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"to employ / occupy → employment, occupation","why":"Stem *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"to support → support","why":"Stem *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk: talking about work","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Complete the small-talk dialogue between Bettina (○) and a friend (◆) with the phrases from the two boxes (shown here as one). Each phrase is used once; the crossed-out one is used in the example.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Difficult. I'm still looking for a job as a translator.","why":"After *Ich* the verb *suche* follows.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ I've already written several applications but only got rejections.","why":"Perfekt: *habe … geschrieben*, matching *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Have you never thought of going freelance? Lots of translators do.","why":"*daran denken* + *zu* + infinitive; *daran* points to the *zu*-clause.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Yes, that's true. But it's really stressful always looking for jobs. And there's a lot of competition.","why":"*Es ist* + adjective + *zu* + infinitive.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ But how are you? Do you still have so much work?","why":"The answer *Ja, leider* needs a yes/no question.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Yes, unfortunately. Several people at our company are off sick at the moment. I have to stand in for two colleagues. And that right now, when we have so many orders!","why":"*vertreten* = to stand in for someone.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ What exactly do you do now, actually?","why":"A W-question: *Was* + verb *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Isn't it tiring always driving from one building site to the next?","why":"*Ist das nicht anstrengend, … zu* + infinitive?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ Sometimes, yes, but mostly I enjoy the work. I get on well with the customers and colleagues. By the way, my company is looking for someone for the office. Don't you want to apply?","why":"*mit jemandem gut zurechtkommen* = to get on well with someone (separable).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ What are you thinking! I'm a translator. I'm not interested in a job as a secretary.","why":"*Interesse an* + dative (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ OK, I'll do that. Thanks for the tip. Oh, I'm afraid I have to go now.","why":"A typical way to end small talk.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Complete the short ads. The book gives some letters of each word; type the whole word.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Work in the semester holidays: we are looking for you as a translator of short advertising texts.","why":"*der Übersetzer / die Übersetzerin* = translator.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Work freelance as a cleaner: on Putzfee.net you can offer your service and look for jobs.","why":"*der Auftrag, die Aufträge* = order, job; *nach* + dative plural adds *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Do a training course. We offer interesting seminars in technology and commerce.","why":"*eine Fortbildung machen* = to do further training.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Because the competition never sleeps!","why":"*die Konkurrenz* = the competition (rivals).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Flexible and motivated? We are looking for people who can stand in for our warehouse staff on an hourly basis.","why":"Modal verb *können* + infinitive *vertreten* (no *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Lesson 5 test","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complete the sentences. The book gives some letters of each word; type the whole word.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"The company Müller & Müller is very good and so it has a lot of orders.","why":"*der Auftrag, die Aufträge* = order(s); *viele* needs the plural."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"Ms Brügger is responsible for 200 employees.","why":"*die Verantwortung für* + accusative = responsibility for."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"The company makes the furniture from Swiss wood.","why":"*herstellen* = to make, manufacture; separable: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario works as a waiter in a restaurant.","why":"*der Serviceangestellte* = waiter (Swiss usage); after *als* without an article the ending is *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter is responsible for checking and repairing the machine tools.","why":"*zuständig sein für* = to be responsible for."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"The company Müller & Müller offers its employees a lot of further training.","why":"*die Fortbildung, die Fortbildungen*; *viele* needs the plural."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Rewrite each sentence with the beginning given, using *zu* + infinitive. Type only the part after the comma.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"I enjoy working with my colleagues.","why":"*die Zusammenarbeit* → the verb *zusammenarbeiten*, separable: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"I could well imagine working as a nurse.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"The careers adviser promises to help with choosing a career.","why":"*die Hilfe* → the verb *helfen*: *zu helfen* at the end.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Complete with *während*, *innerhalb* or *ausserhalb* plus the article in the right form (genitive). The book gives the first letter of the article.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"During the interview you are of course welcome to ask questions.","why":"*während* + genitive neuter: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Please let us know within a week whether you are coming.","why":"*innerhalb* + genitive feminine: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"You can reach me by phone, or by e-mail outside office hours.","why":"*ausserhalb* + genitive plural: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Match each question with the answer (1–5). Type the number.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Have you never thought of changing jobs? → 1 No, I can't imagine that.","why":"A question about an idea: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"What exactly do you do now? → 4 I'm just finishing my apprenticeship as a painter.","why":"A W-question about your job needs a fact as the answer."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Isn't it stressful to work at night? → 2 No, I don't think so.","why":"*Ist es nicht stressig …?* asks for an opinion: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Do you still have so much work? → 3 Yes, I have to stand in for a colleague.","why":"Yes/no question; the reason for the work: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Focus on work: negotiating","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Four good tips","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"What are these tips for? Skim the text and type the right answer. (Exercises 2 and 3 on this page are listening tasks and are left out.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"For conversations with the employer","why":"The tips are about talking money in the job interview, with the head of HR.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"What is right? Read again. Type *richtig* (right) or *falsch* (wrong) after each sentence; in the book you tick only the right ones.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"It is the head of HR's job to raise the subject of pay. → right","why":"Tip 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"At the new job you first get the same pay as at your old company. → wrong","why":"Tip 2 and 3: your last salary is only the basis; you can ask for more.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"If you want more pay, you should give good reasons for it. → right","why":"Tip 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"If the head of HR doesn't agree with your proposal, there's nothing more you can do. → wrong","why":"Tip 4: be flexible and make other proposals (training paid, more pay after six months).","source":"hueber"}]}]}]},{"id":"05-um-zu-damit-statt-ohne-reklamation","no":5,"title":"Lektion 6","title_en":"Purpose with um … zu and damit, instead of / without, verbs with es, sales talk and complaints · Lesson 6 test","added":"2026-11-18","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 6","pages":[{"page":"AB 150","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"It isn't easy, but it's worth it.","exercises":[{"no":"1","tag":"A2","instruction":"Ordnen Sie zu.","instruction_en":"Complete Anna's e-mail with the expressions with *es* from the box. Each one is used once; *geht es* is used in the example. Where an expression has *…*, other words go in between: type the two parts into the two gaps.","phrases":["geht es (Beispiel)","Es war","Es gibt","ist es … gelaufen","es … dunkel ist","wird es … schwierig","schwer es mir fällt","Es ist Sommer","regnet es","hat es … gefallen","es ist … kalt","ist es … ein Uhr","lohnt es sich"],"example":[{"label":"a","text":"Hallo Tim / Wie **geht es** Dir? Bei mir ist alles bestens."}],"items":[{"label":"b","text":"___, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","gaps":[["Es ist Sommer"]],"solution":"**Es ist Sommer**, überall sieht man Blumen und ich bin viel draussen. Ich liebe diese Jahreszeit!","en":"It's summer, there are flowers everywhere and I'm outside a lot. I love this season!","why":"*es* + *sein* + a season or time of day: *Es ist Sommer / Nacht / vier Uhr*.","source":"platzhalter"},{"label":"c","text":"Seit ein paar Tagen ___ zwar, aber schlechtes Wetter stört mich ja nicht.","gaps":[["regnet es"]],"solution":"Seit ein paar Tagen **regnet es** zwar, aber schlechtes Wetter stört mich ja nicht.","en":"It's been raining for a few days, but bad weather doesn't bother me.","why":"Weather verbs always have *es* as subject. *Seit ein paar Tagen* is in position 1, so *es* comes after the verb: *regnet es*.","source":"platzhalter"},{"label":"d","text":"Hauptsache, ___ nicht ___.","gaps":[["es ist"],["kalt"]],"solution":"Hauptsache, **es ist** nicht **kalt**.","en":"The main thing is that it isn't cold.","why":"Weather with an adjective: *es ist kalt / heiss*. *nicht* goes before *kalt*.","source":"platzhalter"},{"label":"e","text":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! ___ wirklich aufregend, …","gaps":[["Es war"]],"solution":"Du, ich hatte heute Vormittag ein Vorstellungsgespräch! **Es war** wirklich aufregend, …","en":"Hey, I had a job interview this morning! It was really exciting, …","why":"General *es* + *sein* + adjective, here in the Präteritum: *Es war aufregend*.","source":"korrelat"},{"label":"f","text":"… aber eigentlich ___ ziemlich gut ___. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","gaps":[["ist es"],["gelaufen"]],"solution":"… aber eigentlich **ist es** ziemlich gut **gelaufen**. Die Leute sind sehr nett und die Arbeit ist abwechslungsreich.","en":"… but actually it went quite well. The people are very nice and the work is varied.","why":"*Es ist gut gelaufen* = it went well (Perfekt with *sein*). *eigentlich* is in position 1, so *ist es*.","source":"platzhalter"},{"label":"g","text":"___ nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","gaps":[["Es gibt"]],"solution":"**Es gibt** nur leider ein Problem: Ich soll morgens um 7 Uhr (!) anfangen zu arbeiten. So schlimm!","en":"There's just one problem, unfortunately: I'm supposed to start work at 7 (!) in the morning. So awful!","why":"*es gibt* + accusative = there is / there are: *Es gibt ein Problem*.","source":"platzhalter"},{"label":"h","text":"Du weisst doch, wie ___, früh aufzustehen.","gaps":[["schwer es mir fällt"]],"solution":"Du weisst doch, wie **schwer es mir fällt**, früh aufzustehen.","en":"You know how hard I find it to get up early.","why":"*Es fällt mir schwer, … zu …* = I find it hard to … In the *wie*-clause the verb goes to the end: *wie schwer es mir fällt*.","source":"korrelat"},{"label":"i","text":"Vor allem im Winter, wenn ___ noch ___, …","gaps":[["es"],["dunkel ist"]],"solution":"Vor allem im Winter, wenn **es** noch **dunkel ist**, …","en":"Especially in winter, when it is still dark, …","why":"*Es ist dunkel* (time of day, light). In the *wenn*-clause the verb goes to the end: *wenn es noch dunkel ist*.","source":"platzhalter"},{"label":"j","text":"… dann ___ wirklich ___ für mich.","gaps":[["wird es"],["schwierig"]],"solution":"… dann **wird es** wirklich **schwierig** für mich.","en":"… then it gets really difficult for me.","why":"*Es wird schwierig* = it gets difficult. *dann* is in position 1, so *wird es*.","source":"korrelat"},{"label":"k","text":"Mir ___ in der Firma zwar sehr gut ___, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","gaps":[["hat es"],["gefallen"]],"solution":"Mir **hat es** in der Firma zwar sehr gut **gefallen**, aber ich weiss nicht, ob ich das mit dem frühen Aufstehen schaffe. Was rätst Du mir?","en":"I really liked it at the company, but I don't know if I'll manage the early starts. What do you advise me?","why":"*Es gefällt mir* = I like it; Perfekt: *Es hat mir gefallen*. Here *Mir* is in position 1.","source":"korrelat"},{"label":"l","text":"P.S.: Oh je, jetzt ___ schon wieder ___ nachts.","gaps":[["ist es"],["ein Uhr"]],"solution":"P.S.: Oh je, jetzt **ist es** schon wieder **ein Uhr** nachts.","en":"P.S. Oh dear, it's already one o'clock at night again.","why":"Clock time: *Es ist ein Uhr*. *jetzt* is in position 1, so *ist es*.","source":"platzhalter"},{"label":"m","text":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht ___ und ich bin dann am Morgen plötzlich immer topfit?","gaps":[["lohnt es sich"]],"solution":"Vielleicht sollte ich einfach mal früher ins Bett gehen? Wer weiss, vielleicht **lohnt es sich** und ich bin dann am Morgen plötzlich immer topfit?","en":"Maybe I should just go to bed earlier? Who knows, maybe it's worth it and then I'll suddenly always be on top form in the morning?","why":"*Es lohnt sich* = it's worth it. *vielleicht* is in position 1, so *lohnt es sich*.","source":"platzhalter"}]},{"no":"2","tag":"A2","instruction":"Machen Sie eine Tabelle und ergänzen Sie die Ausdrücke mit *es* aus 1.","instruction_en":"Sort the expressions with *es* from exercise 1 into four groups. Type the group: *Allgemein* (general), *Tages-/Jahreszeiten* (times of day and seasons), *Wetter* (weather) or *Befinden* (how someone is).","example":[{"label":"Befinden","text":"Wie geht es Dir? → **Befinden**"}],"items":[{"label":"1","text":"Es ist Sommer. → ___","gaps":[["Tages-/Jahreszeiten","Jahreszeiten","Tageszeiten","Jahreszeit","Tages- und Jahreszeiten"]],"solution":"Es ist Sommer. → **Tages-/Jahreszeiten**","en":"It's summer. → times of day and seasons","why":"A season.","source":"hueber"},{"label":"2","text":"regnet es → ___","gaps":[["Wetter"]],"solution":"regnet es → **Wetter**","en":"it rains → weather","why":"Weather verb.","source":"hueber"},{"label":"3","text":"es ist kalt → ___","gaps":[["Wetter"]],"solution":"es ist kalt → **Wetter**","en":"it's cold → weather","why":"Temperature is weather.","source":"hueber"},{"label":"4","text":"Es war (aufregend) → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es war (aufregend) → **Allgemein**","en":"It was (exciting) → general","why":"*es* + *sein* + adjective about a situation.","source":"hueber"},{"label":"5","text":"es ist gelaufen → ___","gaps":[["Allgemein","allgemein"]],"solution":"es ist gelaufen → **Allgemein**","en":"it went (well) → general","why":"How something went: a general expression.","source":"hueber"},{"label":"6","text":"Es gibt → ___","gaps":[["Allgemein","allgemein"]],"solution":"Es gibt → **Allgemein**","en":"There is → general","why":"*es gibt* = there is / there are.","source":"hueber"},{"label":"7","text":"schwer es mir fällt → ___","gaps":[["Allgemein","allgemein"]],"solution":"schwer es mir fällt → **Allgemein**","en":"how hard I find it → general","why":"*es fällt mir schwer* = I find it hard.","source":"hueber"},{"label":"8","text":"es dunkel ist → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"es dunkel ist → **Tages-/Jahreszeiten**","en":"it's dark → times of day","why":"Dark = time of day.","source":"hueber","check":"The official key puts *es ist dunkel* with the times of day. You could also see it as weather; ask your teacher if your class sorted it differently."},{"label":"9","text":"wird es schwierig → ___","gaps":[["Allgemein","allgemein"]],"solution":"wird es schwierig → **Allgemein**","en":"it gets difficult → general","why":"*es* + *werden* + adjective about a situation.","source":"hueber"},{"label":"10","text":"hat es gefallen → ___","gaps":[["Allgemein","allgemein"]],"solution":"hat es gefallen → **Allgemein**","en":"I liked it → general","why":"*es gefällt mir* = I like it.","source":"hueber"},{"label":"11","text":"ist es ein Uhr → ___","gaps":[["Tages-/Jahreszeiten","Tageszeiten","Tageszeit","Jahreszeiten","Tages- und Jahreszeiten"]],"solution":"ist es ein Uhr → **Tages-/Jahreszeiten**","en":"it's one o'clock → times of day","why":"Clock time.","source":"hueber"},{"label":"12","text":"lohnt es sich → ___","gaps":[["Allgemein","allgemein"]],"solution":"lohnt es sich → **Allgemein**","en":"it's worth it → general","why":"*es lohnt sich* = it's worth it.","source":"hueber"}]},{"no":"3","tag":"A2","instruction":"Wo fehlt *es*? Ergänzen Sie wie im Beispiel.","instruction_en":"Where is *es* missing? Read Fatima's e-mail. For each sentence below, write it again with *es* in the right place. One sentence is correct as it is: then type it unchanged.","reading":[{"label":"E-Mail","text":"Liebe Saskia\nist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe. Ich hoffe, dass euch gut geht. Seit wir in Gossau leben, ist viel passiert. Jetzt läuft ganz gut, aber am Anfang gab viele Probleme. Für unsere Kinder war besonders schwer. Sie haben ihre Freunde sehr vermisst und hatten Probleme mit der Sprache. Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt. Sie gehen ja jetzt auch zur Schule und haben andere Kinder kennengelernt. Übrigens gehe ich jetzt auch wieder in eine Schule – in eine Sprachschule. Ich besuche einen B1-Kurs. Das macht mir grosse Freude. So, jetzt ist gleich 9 Uhr. Ich muss Schluss machen. Mein Kurs fängt in einer halben Stunde an.\nBis bald, Deine Fatima"}],"example":[{"label":"Beispiel","text":"**Es** ist schon ein paar Monate her, dass ich Dir das letzte Mal geschrieben habe."}],"items":[{"label":"1","lead":"Ich hoffe, dass euch gut geht.","text":"","accept":["Ich hoffe, dass es euch gut geht."],"solution":"**Ich hoffe, dass es euch gut geht.**","en":"I hope you are all well.","why":"*Wie geht es euch?* → *dass es euch gut geht*: *es* is the subject of *gehen* in this sense and can't be left out.","source":"platzhalter"},{"label":"2","lead":"Seit wir in Gossau leben, ist viel passiert.","text":"","accept":["Seit wir in Gossau leben, ist viel passiert."],"solution":"**Seit wir in Gossau leben, ist viel passiert.**","en":"A lot has happened since we have lived in Gossau.","why":"No *es*: *viel* is the subject, and the *seit*-clause fills position 1.","source":"platzhalter"},{"label":"3","lead":"Jetzt läuft ganz gut, aber am Anfang gab viele Probleme.","text":"","accept":["Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme."],"solution":"**Jetzt läuft es ganz gut, aber am Anfang gab es viele Probleme.**","en":"Things are going quite well now, but at the beginning there were a lot of problems.","why":"Two gaps: *es läuft gut* (things go well) and *es gab* (there were, Präteritum of *es gibt*). With *jetzt* / *am Anfang* in position 1, *es* follows the verb.","source":"platzhalter"},{"label":"4","lead":"Für unsere Kinder war besonders schwer.","text":"","accept":["Für unsere Kinder war es besonders schwer."],"solution":"**Für unsere Kinder war es besonders schwer.**","en":"It was especially hard for our children.","why":"*es* + *sein* + adjective: *es war schwer*.","source":"platzhalter"},{"label":"5","lead":"Aber jetzt ist schon viel besser und sie haben sich an das Leben hier gewöhnt.","text":"","accept":["Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt."],"solution":"**Aber jetzt ist es schon viel besser und sie haben sich an das Leben hier gewöhnt.**","en":"But now it's already much better and they have got used to life here.","why":"*es ist besser*: the situation has no other subject, so *es* is needed.","source":"platzhalter"},{"label":"6","lead":"So, jetzt ist gleich 9 Uhr.","text":"","accept":["So, jetzt ist es gleich 9 Uhr."],"solution":"**So, jetzt ist es gleich 9 Uhr.**","en":"Right, it's nearly 9 o'clock now.","why":"Clock time: *es ist 9 Uhr*.","source":"platzhalter"}]}]},{"page":"AB 151","heading":"A  Es ist nicht leicht, aber es lohnt sich.","heading_en":"It isn't easy, but it's worth it.","exercises":[{"no":"4","tag":"A3","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"What is right? Read the text about a village get-together and type the word that fits each gap. The two choices are given above each sentence.","reading":[{"label":"Stammtisch der Kulturen","text":"In unserem Dorf gibt es seit einiger Zeit am ersten Freitag im Monat einen Stammtisch der Kulturen. Dahin kommen alle, die Interesse an einem (a) Treffen mit Menschen aus aller Welt haben. Der Stammtisch ist ein grosser Erfolg geworden. Das war nicht immer so. Am Anfang war es eigentlich ein (b) und es kamen nur sehr wenige Teilnehmer. Es waren (c) fünf bis zehn da. Es war einfach so, dass die Leute aus der Region zuerst dachten, dass das Treffen nur für Migranten ist. Inzwischen kommen aber auch immer mehr Schweizer, (d) sind es oft sogar über 30 Leute pro Treffen. Alle helfen gratis mit und so funktioniert der Stammtisch ohne (e) Unterstützung."}],"example":[{"label":"a","text":"Dahin kommen alle, die Interesse an einem **interkulturellen** Treffen mit Menschen aus aller Welt haben."}],"items":[{"label":"b","lead":"Heimweh / Experiment","text":"Am Anfang war es eigentlich ein ___ und es kamen nur sehr wenige Teilnehmer.","gaps":[["Experiment"]],"solution":"Am Anfang war es eigentlich ein **Experiment** und es kamen nur sehr wenige Teilnehmer.","en":"At the beginning it was really an experiment and only very few people came.","why":"*Heimweh* (homesickness) makes no sense here; a new idea that may or may not work is an *Experiment*.","source":"hueber"},{"label":"c","lead":"mindestens / höchstens","text":"Es waren ___ fünf bis zehn da.","gaps":[["höchstens"]],"solution":"Es waren **höchstens** fünf bis zehn da.","en":"There were at most five to ten people there.","why":"*nur sehr wenige* → *höchstens* (at most), not *mindestens* (at least).","source":"hueber"},{"label":"d","lead":"mindestens / mittlerweile","text":"Inzwischen kommen aber auch immer mehr Schweizer, ___ sind es oft sogar über 30 Leute pro Treffen.","gaps":[["mittlerweile"]],"solution":"Inzwischen kommen aber auch immer mehr Schweizer, **mittlerweile** sind es oft sogar über 30 Leute pro Treffen.","en":"Meanwhile more and more Swiss people come too; by now there are often even over 30 people per meeting.","why":"*mittlerweile* = by now, meanwhile (like *inzwischen*).","source":"hueber"},{"label":"e","lead":"finanzielle / spezielle","text":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne ___ Unterstützung.","gaps":[["finanzielle"]],"solution":"Alle helfen gratis mit und so funktioniert der Stammtisch ohne **finanzielle** Unterstützung.","en":"Everyone helps for free, so the get-together works without financial support.","why":"*gratis* (for free) → no money is needed: *finanzielle Unterstützung*.","source":"hueber"}]},{"no":"5","tag":"A3","instruction":"Ergänzen Sie.","instruction_en":"Complete the sentences. The book gives some letters of each word (shown above the sentence); type the whole word.","example":[{"label":"c","text":"Ich mag den Frühling und den Sommer. Aber der Winter ist für mich die schönste **Jahreszeit**."}],"items":[{"label":"a","lead":"H _ _ _ _ h","text":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe ___.","gaps":[["Heimweh"]],"solution":"Ich bin traurig, weil ich nicht zu Hause bin. Ich habe **Heimweh**.","en":"I'm sad because I'm not at home. I'm homesick.","why":"*das Heimweh* = homesickness; *Heimweh haben*.","source":"hueber"},{"label":"b","lead":"G _ _ _ r _ _","text":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen ___.","gaps":[["Gewürze"]],"solution":"Das Wichtigste beim Kochen von indischen Gerichten sind die richtigen **Gewürze**.","en":"The most important thing when cooking Indian dishes is the right spices.","why":"*das Gewürz, die Gewürze* = spice(s); plural because of *sind*.","source":"hueber"},{"label":"d","lead":"G _ _ _ _ ä _ _ _ _ _ _ _ e","text":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche ___.","gaps":[["Geschäftsleute"]],"solution":"Meine Grosseltern hatten mehrere Geschäfte. Sie waren erfolgreiche **Geschäftsleute**.","en":"My grandparents had several shops. They were successful business people.","why":"*die Geschäftsleute* = plural of *der Geschäftsmann / die Geschäftsfrau*.","source":"hueber"},{"label":"e","lead":"R _ _ _ _ c _ _ _","text":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine ___.","gaps":[["Rücksicht"]],"solution":"Unser Nachbar hört zu jeder Tageszeit laute Musik. Das stört uns alle, aber er nimmt keine **Rücksicht**.","en":"Our neighbour plays loud music at all times of day. It bothers us all, but he doesn't show any consideration.","why":"*Rücksicht nehmen (auf)* = to be considerate (of).","source":"hueber"},{"label":"f","lead":"f _ _ _ _ z _ _ _ _ _ _  R _ _ _ _ _","text":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein ___ ___.","gaps":[["finanzielles"],["Risiko"]],"solution":"Wenn man sich mit einem Geschäft selbstständig macht, ist das oft ein **finanzielles** **Risiko**.","en":"When you set up your own business, it's often a financial risk.","why":"*das Risiko* is neuter, so *ein finanzielles Risiko*.","source":"hueber"},{"label":"g","lead":"l _ _ _","text":"Mein Onkel hat viele gute Ideen. Er ___ fast jedes Problem.","gaps":[["löst"]],"solution":"Mein Onkel hat viele gute Ideen. Er **löst** fast jedes Problem.","en":"My uncle has lots of good ideas. He solves almost every problem.","why":"*ein Problem lösen* = to solve a problem; *er löst*.","source":"hueber"}]},{"no":"6","tag":"A4","instruction":"Buchstaben und Laute: *b – p, g – k, d – t*","instruction_en":"Letters and sounds: *b – p, g – k, d – t*. (Parts a and b are listening tasks and are left out.)","part":"c","part_instruction":"Ergänzen Sie die Regel.","part_instruction_en":"Complete the rule: how do you say *b, d, g* at the end of a word? Look at *halb, Geld, Tag*.","items":[{"label":"c","text":"Am Wortende spricht man *b, d, g* wie ___.","gaps":[["p, t, k","p t k","p, t und k","p,t,k"]],"solution":"Am Wortende spricht man *b, d, g* wie **p, t, k**.","en":"At the end of a word you pronounce *b, d, g* like *p, t, k*.","why":"*halb* sounds like \"halp\", *Geld* like \"Gelt\", *Tag* like \"Tak\". The same happens before another consonant: *Erfolg*, *Auftrag*, *ab und zu*.","source":"hueber"}]}]},{"page":"AB 152","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"I want to be at the shop so that I can wait there.","exercises":[{"no":"7","tag":"B1","instruction":"Margaretas Ziele. Ergänzen Sie.","instruction_en":"Margareta's goals. Each line shows a wish (left) and the same idea as a purpose with *um … zu* (right). Fill the gaps on whichever side is missing.","example":[{"label":"a","lead":"Wozu ist Margareta in die Schweiz gekommen?","text":"Sie möchte ihr Deutsch verbessern. → Margareta ist in die Schweiz gekommen, **um** ihr Deutsch **zu verbessern**."}],"items":[{"label":"b","text":"Sie ___ eine Ausbildung ___. → um eine Ausbildung zu machen.","gaps":[["möchte"],["machen"]],"solution":"Sie **möchte** eine Ausbildung **machen**. → um eine Ausbildung zu machen.","en":"She would like to do an apprenticeship. → in order to do an apprenticeship.","why":"The wish: *möchte* + infinitive at the end. *um … zu* drops the modal verb.","source":"g6865"},{"label":"c","text":"Sie möchte selbstständiger werden. → ___ selbstständiger ___.","gaps":[["um"],["zu werden"]],"solution":"Sie möchte selbstständiger werden. → **um** selbstständiger **zu werden**.","en":"She would like to become more independent. → in order to become more independent.","why":"*um* starts the group, *zu* + infinitive ends it. *möchte* disappears.","source":"g6865"},{"label":"d","text":"Sie ___ Geld ___. → um Geld zu verdienen.","gaps":[["möchte"],["verdienen"]],"solution":"Sie **möchte** Geld **verdienen**. → um Geld zu verdienen.","en":"She would like to earn money. → in order to earn money.","why":"Back to the wish: *Sie möchte Geld verdienen.*","source":"g6865"},{"label":"e","text":"Sie möchte in der Nähe ihres Freundes sein. → ___ in der Nähe ihres Freundes ___.","gaps":[["um"],["zu sein"]],"solution":"Sie möchte in der Nähe ihres Freundes sein. → **um** in der Nähe ihres Freundes **zu sein**.","en":"She would like to be near her boyfriend. → in order to be near her boyfriend.","why":"*um … zu sein*; *ihres Freundes* is genitive after *in der Nähe*.","source":"g6865"}]},{"no":"8","tag":"B1","instruction":"Wozu machen die Leute das? Ordnen Sie zu und ergänzen Sie die Sätze mit *um … zu*.","instruction_en":"Why do the people do this? Choose the goal from the box that fits each sentence and add it as *um … zu* + infinitive. *gesund bleiben* is used in the example.","phrases":["frische Zutaten und Gewürze kaufen","als Erster im Büro sein","gesund bleiben (Beispiel)","einen wichtigen Kunden treffen","bessere Chancen auf dem Arbeitsmarkt haben"],"example":[{"label":"a","text":"Miguel geht dreimal pro Woche ins Fitnessstudio, **um gesund zu bleiben**."}],"items":[{"label":"b","text":"Peter steht von Montag bis Freitag sehr früh auf, ___.","gaps":[["um als Erster im Büro zu sein"]],"solution":"Peter steht von Montag bis Freitag sehr früh auf, **um als Erster im Büro zu sein**.","en":"Peter gets up very early from Monday to Friday so that he is the first in the office.","why":"Same person (Peter), so *um … zu*; *sein* goes last with *zu*.","source":"g6865"},{"label":"c","text":"Am Wochenende gehe ich immer auf den Markt, ___.","gaps":[["um frische Zutaten und Gewürze zu kaufen"]],"solution":"Am Wochenende gehe ich immer auf den Markt, **um frische Zutaten und Gewürze zu kaufen**.","en":"At the weekend I always go to the market to buy fresh ingredients and spices.","why":"Everything that belongs to *kaufen* comes before *zu kaufen*.","source":"g6865"},{"label":"d","text":"Herr Aryan fährt morgen nach Genf, ___.","gaps":[["um einen wichtigen Kunden zu treffen"]],"solution":"Herr Aryan fährt morgen nach Genf, **um einen wichtigen Kunden zu treffen**.","en":"Mr Aryan is going to Geneva tomorrow to meet an important client.","why":"*um … zu treffen*; the object *einen wichtigen Kunden* goes in the middle.","source":"g6865"},{"label":"e","text":"Sabina macht eine berufliche Weiterbildung, ___.","gaps":[["um bessere Chancen auf dem Arbeitsmarkt zu haben"]],"solution":"Sabina macht eine berufliche Weiterbildung, **um bessere Chancen auf dem Arbeitsmarkt zu haben**.","en":"Sabina is doing further job training to have better chances on the job market.","why":"Same person (Sabina): *um … zu haben*.","source":"g6865"}]},{"no":"9","tag":"B1","instruction":"Wozu ist Yaroslav in die Schweiz gekommen?","instruction_en":"Why did Yaroslav come to Switzerland?","part":"a","part_instruction":"Lesen Sie den Text und ergänzen Sie die Gründe.","part_instruction_en":"Read the text and complete the reasons with words from the text.","reading":[{"label":"Abenteuer Ausland: Wozu sind Sie in die Schweiz gekommen? – Yaroslav Ivanenko, 38","text":"Meine Frau und ich wollten schon lange eine neue Perspektive im Leben finden. Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben. Bei mir war das anders. Ich bin IT-Spezialist und habe jahrelang als Programmierer in einer Softwarefirma gearbeitet. In unserem Land gibt es aber weniger Entwicklungsmöglichkeiten für meine Berufsbranche. Auch für unsere Kinder habe ich mir gewünscht, dass sie einmal eine gute Schule besuchen können. Aber die sind in unserer Heimat teuer. In einem internationalen Job-Portal im Internet habe ich dann gesehen, dass in der Schweiz Programmierer gesucht werden. Ich habe mich bei mehreren Firmen beworben und hatte grosses Glück. Gleich eins der ersten Vorstellungsgespräche, das ich über Skype geführt habe, war so positiv, dass ich von der Firma sofort ein Jobangebot erhalten habe. Die erste Zeit habe ich noch von der Ukraine aus gearbeitet, aber nach meiner Probezeit habe ich über die Firma eine offizielle Arbeitsbewilligung für die Schweiz bekommen. Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist. So haben wir uns entschlossen, mit den Kindern in die Schweiz zu ziehen. Es war nicht immer leicht für uns, aber jetzt sind wir einfach nur dankbar, dass wir diese Chance bekommen haben."}],"example":[{"label":"1","text":"Yaroslav und seine Frau können **eine neue Perspektive** finden."}],"items":[{"label":"2","text":"Seine Frau kann ___ leben.","gaps":[["in einer Stadt im Ausland"]],"solution":"Seine Frau kann **in einer Stadt im Ausland** leben.","en":"His wife can live in a city abroad.","why":"*Meine Frau wollte zum Beispiel gern in einer Stadt im Ausland leben.*","source":"hueber"},{"label":"3","text":"Seine Kinder können ___ besuchen.","gaps":[["eine gute Schule"]],"solution":"Seine Kinder können **eine gute Schule** besuchen.","en":"His children can go to a good school.","why":"*… dass sie einmal eine gute Schule besuchen können.*","source":"hueber"},{"label":"4","text":"Das ganze Programmiererteam ist ___.","gaps":[["in Zug"]],"solution":"Das ganze Programmiererteam ist **in Zug**.","en":"The whole programming team is in Zug.","why":"*Mein Chef wollte unbedingt, dass das ganze Programmiererteam in Zug ist.*","source":"hueber"}]}]},{"page":"AB 153","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"I want to be at the shop so that I can wait there.","exercises":[{"no":"9","part":"b","part_instruction":"Schreiben Sie die Sätze neu mit *damit*.","part_instruction_en":"Rewrite the reasons from a as *damit*-clauses: *Yaroslav ist in die Schweiz gekommen, damit …* The verb goes to the end.","example":[{"label":"1","text":"Yaroslav ist in die Schweiz gekommen, **damit er und seine Frau eine neue Perspektive finden können**."}],"items":[{"label":"2","lead":"Seine Frau kann in einer Stadt im Ausland leben.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann.","damit seine Frau in einer Stadt im Ausland leben kann"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Frau in einer Stadt im Ausland leben kann.**","en":"Yaroslav came to Switzerland so that his wife can live in a city abroad.","why":"Different person (his wife), so only *damit*; *kann* goes to the very end.","source":"damit"},{"label":"3","lead":"Seine Kinder können eine gute Schule besuchen.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können.","damit seine Kinder eine gute Schule besuchen können"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit seine Kinder eine gute Schule besuchen können.**","en":"Yaroslav came to Switzerland so that his children can go to a good school.","why":"Different person (his children): *damit … besuchen können*.","source":"damit"},{"label":"4","lead":"Das ganze Programmiererteam ist in Zug.","text":"","accept":["Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist.","damit das ganze Programmiererteam in Zug ist"],"solution":"**Yaroslav ist in die Schweiz gekommen, damit das ganze Programmiererteam in Zug ist.**","en":"Yaroslav came to Switzerland so that the whole programming team is in Zug.","why":"Different subject (the team): *damit … ist*.","source":"damit"}]},{"no":"10","tag":"B1","instruction":"Warum steht Yaroslav früh auf? Lesen Sie und markieren Sie wie im Beispiel. Ergänzen Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"Why does Yaroslav get up early? Look at who does the second action. Same person: write both *damit* and *um … zu*. Different person: only *damit* works.","example":[{"label":"A","lead":"Yaroslav steht früh auf. Er will vor der Arbeit joggen.","text":"Yaroslav steht früh auf, **damit er vor der Arbeit joggen kann**. / Yaroslav steht früh auf, **um vor der Arbeit zu joggen**."},{"label":"B","lead":"Yaroslav steht früh auf. Seine Kinder sollen pünktlich aus dem Haus gehen.","text":"Yaroslav steht früh auf, **damit seine Kinder pünktlich aus dem Haus gehen**."}],"items":[{"label":"A2","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, damit ___.","gaps":[["er in Ruhe seinen Kaffee trinken kann","er seinen Kaffee in Ruhe trinken kann"]],"solution":"Yaroslav steht früh auf, damit **er in Ruhe seinen Kaffee trinken kann**.","en":"Yaroslav gets up early so that he can drink his coffee in peace.","why":"Same person (*er*). *will* becomes *kann* in the *damit*-clause; the verb goes to the end.","source":"damit"},{"label":"A3","lead":"Yaroslav steht früh auf. Er will in Ruhe seinen Kaffee trinken.","text":"Yaroslav steht früh auf, ___.","gaps":[["um in Ruhe seinen Kaffee zu trinken","um seinen Kaffee in Ruhe zu trinken"]],"solution":"Yaroslav steht früh auf, **um in Ruhe seinen Kaffee zu trinken**.","en":"Yaroslav gets up early to drink his coffee in peace.","why":"Same person, so *um … zu* also works: no subject, no *will*.","source":"g6865"},{"label":"B2","lead":"Yaroslav steht früh auf. Das Badezimmer soll dann für die Familie frei sein.","text":"Yaroslav steht früh auf, ___.","gaps":[["damit das Badezimmer dann für die Familie frei ist","damit das Badezimmer für die Familie frei ist"]],"solution":"Yaroslav steht früh auf, **damit das Badezimmer dann für die Familie frei ist**.","en":"Yaroslav gets up early so that the bathroom is then free for the family.","why":"Different subject (*das Badezimmer*): only *damit*. *soll* is dropped: *damit … frei ist*.","source":"damit"}]},{"no":"11","tag":"B1","instruction":"Eine typische Woche von Marcello und seiner Familie. Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","instruction_en":"A typical week for Marcello (A), his wife (B) and their children (C). Join each pair into one sentence. Use *um … zu* when the person is the same, otherwise *damit*. Where both work, either is accepted.","example":[{"label":"A1","lead":"Ich gehe am Morgen früh zur Arbeit. Ich möchte am Abend nicht so spät nach Hause kommen.","text":"Ich gehe am Morgen früh zur Arbeit, **damit ich am Abend nicht so spät nach Hause komme**. / Ich gehe am Morgen früh zur Arbeit, **um am Abend nicht so spät nach Hause zu kommen**."}],"items":[{"label":"A2","lead":"Marcello: Ich fahre einmal pro Woche zum Supermarkt. Meine Frau muss die schweren Einkäufe nicht machen.","text":"","accept":["Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss."],"solution":"**Ich fahre einmal pro Woche zum Supermarkt, damit meine Frau die schweren Einkäufe nicht machen muss.**","en":"I drive to the supermarket once a week so that my wife doesn't have to do the heavy shopping.","why":"Different person (*meine Frau*): only *damit*. Here *muss* stays, because it carries the meaning (*nicht machen muss* = doesn't have to).","source":"damit"},{"label":"B1","lead":"Frau: Ich koche am Mittag zu Hause. Die Kinder sollen etwas Warmes zu essen haben, wenn sie von der Schule kommen.","text":"","accept":["Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen."],"solution":"**Ich koche am Mittag zu Hause, damit die Kinder etwas Warmes zu essen haben, wenn sie von der Schule kommen.**","en":"I cook at home at lunchtime so that the children have something hot to eat when they come home from school.","why":"Different person (*die Kinder*): *damit*; *sollen* is dropped.","source":"damit"},{"label":"B2","lead":"Frau: Ich verbessere mein Deutsch in einem Sprachkurs. Ich will im Alltag gut zurechtkommen.","text":"","accept":["Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.","Ich verbessere mein Deutsch in einem Sprachkurs, damit ich im Alltag gut zurechtkomme."],"solution":"**Ich verbessere mein Deutsch in einem Sprachkurs, um im Alltag gut zurechtzukommen.**","en":"I'm improving my German in a language course so that I can manage well in everyday life.","why":"Same person: both work. *zurechtkommen* is separable: *zurecht**zu**kommen*. *will* is dropped.","source":"g6865"},{"label":"C1","lead":"Kinder: Wir lernen nach der Schule viel am Nachmittag. Wir wollen gute Noten haben und einen guten Abschluss machen.","text":"","accept":["Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.","Wir lernen nach der Schule viel am Nachmittag, damit wir gute Noten haben und einen guten Abschluss machen."],"solution":"**Wir lernen nach der Schule viel am Nachmittag, um gute Noten zu haben und einen guten Abschluss zu machen.**","en":"We study a lot in the afternoon after school so that we get good marks and a good leaving certificate.","why":"Same person (*wir*): both work. With two verbs, each gets its own *zu*.","source":"g6865"},{"label":"C2","lead":"Kinder: Wir helfen im Haushalt. Mama soll nicht alles allein machen.","text":"","accept":["Wir helfen im Haushalt, damit Mama nicht alles allein macht.","Wir helfen im Haushalt, damit Mama nicht alles allein machen muss."],"solution":"**Wir helfen im Haushalt, damit Mama nicht alles allein macht.**","en":"We help with the housework so that Mum doesn't do everything on her own.","why":"Different person (*Mama*): only *damit*; *soll* is dropped.","source":"damit"}]}]},{"page":"AB 154","heading":"B  Ich will bei dem Geschäft sein, um dort zu warten.","heading_en":"I want to be at the shop so that I can wait there.","exercises":[{"no":"12","tag":"B1","marker":"◇","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"What is right? Type *um* or *damit*. Look at the end of the sentence: *zu* + infinitive needs *um*; a conjugated verb at the end needs *damit*.","example":[{"label":"a","text":"Frau Alt betreut ihre Enkel zu Hause, **damit** ihre Tochter berufstätig sein kann."}],"items":[{"label":"b","text":"Jaime lernt und arbeitet viel, ___ sich bald selbstständig zu machen.","gaps":[["um"]],"solution":"Jaime lernt und arbeitet viel, **um** sich bald selbstständig zu machen.","en":"Jaime studies and works a lot in order to set up his own business soon.","why":"*zu machen* at the end → *um*.","source":"g6865"},{"label":"c","text":"Said lernt neben Deutsch auch Englisch, ___ bessere Chancen auf dem Arbeitsmarkt zu haben.","gaps":[["um"]],"solution":"Said lernt neben Deutsch auch Englisch, **um** bessere Chancen auf dem Arbeitsmarkt zu haben.","en":"Said is learning English as well as German to have better chances on the job market.","why":"*zu haben* at the end → *um*.","source":"g6865"},{"label":"d","text":"Irina arbeitet jetzt Vollzeit, ___ ihr Mann eine teure Weiterbildung machen kann.","gaps":[["damit"]],"solution":"Irina arbeitet jetzt Vollzeit, **damit** ihr Mann eine teure Weiterbildung machen kann.","en":"Irina now works full-time so that her husband can do an expensive training course.","why":"New subject *ihr Mann* and *kann* at the end → *damit*.","source":"damit"},{"label":"e","text":"Herr Pfister bezahlt viel Geld, ___ seine Eltern von einer privaten Pflegehelferin gepflegt werden.","gaps":[["damit"]],"solution":"Herr Pfister bezahlt viel Geld, **damit** seine Eltern von einer privaten Pflegehelferin gepflegt werden.","en":"Mr Pfister pays a lot of money so that his parents are cared for by a private care assistant.","why":"New subject *seine Eltern*, passive *gepflegt werden* at the end → *damit*.","source":"damit"}]},{"no":"13","tag":"B1","marker":"◆","instruction":"Wozu macht Marcello das?","instruction_en":"Why does Marcello do this?","part":"a","part_instruction":"Verbinden Sie.","part_instruction_en":"Match each thing Marcello does (1–6) with the person who benefits (*Er, Seine Frau, Sein Team*) and the goal (a–f). Type the person, then the letter.","phrases":["Er","Seine Frau","Sein Team","a soll abends etwas Ruhe haben.","b kann das gemeinsame Projekt pünktlich abschliessen.","c will wochentags früher gehen.","d kann tagsüber die Einkäufe mit dem Auto erledigen.","e kann ungestört seinen Arbeitstag planen.","f will fit bleiben."],"example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen. → **Er**, **f**"}],"items":[{"label":"2","text":"Er ist als Erster im Büro. → ___, ___","gaps":[["Er"],["e"]],"solution":"Er ist als Erster im Büro. → **Er**, **e**","en":"He is the first in the office. → He, e (can plan his working day undisturbed).","why":"An empty office means no interruptions.","source":"hueber"},{"label":"3","text":"Er lässt das Auto zu Hause. → ___, ___","gaps":[["Seine Frau"],["d"]],"solution":"Er lässt das Auto zu Hause. → **Seine Frau**, **d**","en":"He leaves the car at home. → His wife, d (can do the shopping by car during the day).","why":"If he doesn't take the car, his wife can use it.","source":"hueber"},{"label":"4","text":"Er macht manchmal Überstunden. → ___, ___","gaps":[["Sein Team"],["b"]],"solution":"Er macht manchmal Überstunden. → **Sein Team**, **b**","en":"He sometimes works overtime. → His team, b (can finish the joint project on time).","why":"Overtime helps the shared project.","source":"hueber"},{"label":"5","text":"Er arbeitet auch mal am Samstag. → ___, ___","gaps":[["Er"],["c"]],"solution":"Er arbeitet auch mal am Samstag. → **Er**, **c**","en":"He sometimes works on Saturday too. → He, c (wants to leave earlier on weekdays).","why":"Saturday work buys him shorter weekdays.","source":"hueber"},{"label":"6","text":"Er bringt die Kinder ins Bett. → ___, ___","gaps":[["Seine Frau"],["a"]],"solution":"Er bringt die Kinder ins Bett. → **Seine Frau**, **a**","en":"He puts the children to bed. → His wife, a (should have some peace in the evening).","why":"The evening is quiet for her.","source":"hueber"}]},{"no":"13","part":"b","part_instruction":"Schreiben Sie Sätze mit *damit* und *um … zu*, wenn möglich.","part_instruction_en":"Write sentences from your answers in a. Same person (*Er*): *um … zu* or *damit*. Another person: only *damit*. Drop *will* and *soll*.","example":[{"label":"1","text":"Marcello geht dreimal pro Woche joggen, **damit er fit bleibt**. / Marcello geht dreimal pro Woche joggen, **um fit zu bleiben**."}],"items":[{"label":"2","lead":"Er ist als Erster im Büro. / Er kann ungestört seinen Arbeitstag planen.","text":"","accept":["Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.","Er ist als Erster im Büro, damit er ungestört seinen Arbeitstag planen kann.","Marcello ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen."],"solution":"**Er ist als Erster im Büro, um ungestört seinen Arbeitstag zu planen.**","en":"He is the first in the office so that he can plan his working day undisturbed.","why":"Same person: both work.","source":"g6865"},{"label":"3","lead":"Er lässt das Auto zu Hause. / Seine Frau kann tagsüber die Einkäufe mit dem Auto erledigen.","text":"","accept":["Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann."],"solution":"**Er lässt das Auto zu Hause, damit seine Frau tagsüber die Einkäufe mit dem Auto erledigen kann.**","en":"He leaves the car at home so that his wife can do the shopping by car during the day.","why":"Other person: only *damit*.","source":"damit"},{"label":"4","lead":"Er macht manchmal Überstunden. / Sein Team kann das gemeinsame Projekt pünktlich abschliessen.","text":"","accept":["Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann."],"solution":"**Er macht manchmal Überstunden, damit sein Team das gemeinsame Projekt pünktlich abschliessen kann.**","en":"He sometimes works overtime so that his team can finish the joint project on time.","why":"Other subject: only *damit*.","source":"damit"},{"label":"5","lead":"Er arbeitet auch mal am Samstag. / Er will wochentags früher gehen.","text":"","accept":["Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.","Er arbeitet auch mal am Samstag, damit er wochentags früher gehen kann."],"solution":"**Er arbeitet auch mal am Samstag, um wochentags früher zu gehen.**","en":"He sometimes works on Saturday too so that he can leave earlier on weekdays.","why":"Same person: both work; *will* is dropped.","source":"g6865"},{"label":"6","lead":"Er bringt die Kinder ins Bett. / Seine Frau soll abends etwas Ruhe haben.","text":"","accept":["Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat."],"solution":"**Er bringt die Kinder ins Bett, damit seine Frau abends etwas Ruhe hat.**","en":"He puts the children to bed so that his wife has some peace in the evening.","why":"Other person: *damit*; *soll* is dropped.","source":"damit"}]},{"no":"14","tag":"B3","instruction":"Beruf und Karriere – was ist wichtig, um Erfolg im Job zu haben? Markieren Sie noch fünf Wörter und ordnen Sie zu.","instruction_en":"Job and career: what matters for success at work? Find five more words in the letter grid and complete the sentences. *Kompetenzen* is the example. Type adjectives in lower case.","reading":[{"label":"Buchstabengitter","text":"DLKJLDGDKJLKDLGKOMPETENZENLLSKOMMUNIKATIVEDJG\nLSKDENGAGEMENTJGKDÖLGÖGLLKGLKONFLIKTFÄHIGLÖFJA\nFLAGJSTEAMFÄHIGJGSLGJSLMOTIVATIONSLGSLKGDJAFJFLA"}],"example":[{"label":"a","text":"Personalfachleute sagen: Man braucht nicht nur fachliche, sondern auch soziale **Kompetenzen**, wenn man im Beruf erfolgreich sein will."}],"items":[{"label":"b","text":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie ___.","gaps":[["teamfähig"]],"solution":"Zum Beispiel ist es wichtig, dass eine Person gut im Team arbeiten kann und auch Kompromisse eingeht. Dann ist sie **teamfähig**.","en":"For example, it's important that a person can work well in a team and also makes compromises. Then they are a good team player.","why":"*teamfähig* = able to work in a team.","source":"hueber"},{"label":"c","text":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie ___.","gaps":[["konfliktfähig"]],"solution":"Wenn sich Kollegen streiten, aber schliesslich gemeinsam eine gute Lösung für ihr Problem finden, dann sind sie **konfliktfähig**.","en":"If colleagues argue but in the end find a good solution to their problem together, they can handle conflict.","why":"*konfliktfähig* = able to deal with conflict.","source":"hueber"},{"label":"d","text":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute ___ Kompetenzen.","gaps":[["kommunikative"]],"solution":"Wer offen ist, sich gut mit Menschen unterhalten, aber auch gut zuhören kann, hat gute **kommunikative** Kompetenzen.","en":"Anyone who is open, can talk well with people but can also listen well has good communication skills.","why":"Adjective before a plural noun after *gute*: *kommunikative Kompetenzen*.","source":"hueber"},{"label":"e","text":"Auf jeden Fall muss ein Mitarbeiter ___ und ___ zeigen, um im Beruf erfolgreich zu sein.","gaps":[["Motivation","Engagement"],["Engagement","Motivation"]],"solution":"Auf jeden Fall muss ein Mitarbeiter **Motivation** und **Engagement** zeigen, um im Beruf erfolgreich zu sein.","en":"In any case an employee must show motivation and commitment to be successful at work.","why":"*die Motivation* and *das Engagement* (commitment); either order.","source":"hueber"}]}]},{"page":"AB 155","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Doing something instead of just dreaming","exercises":[{"no":"15","tag":"C1","instruction":"Unzufrieden im Job","instruction_en":"Unhappy at work","part":"a","part_instruction":"In welchem Satz steht *nicht/kein*? Markieren Sie.","part_instruction_en":"Compare the two short sentences with the long one. Which word for \"not / no\" disappears in the *statt … zu* or *ohne … zu* version? Type it.","example":[{"label":"1","text":"Ich bringe lieber meinen eigenen Laptop mit. Ich benütze **nicht** den alten Computer in der Firma. / Ich bringe lieber meinen eigenen Laptop mit, statt den alten Computer in der Firma zu benützen."}],"items":[{"label":"2","text":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → ___","gaps":[["keinen","kein"]],"solution":"Der Chef hat immer schlechte Laune. Er hat keinen Grund dafür. / Der Chef hat immer schlechte Laune, ohne einen Grund dafür zu haben. → **keinen**","en":"The boss is always in a bad mood. He has no reason for it. / The boss is always in a bad mood without having a reason for it. → keinen","why":"*ohne* already means \"not\": *keinen Grund* becomes *einen Grund* after *ohne*.","source":"komma"}]},{"no":"15","part":"b","part_instruction":"Welche Sätze sind richtig? Vergleichen Sie mit a und kreuzen Sie an.","part_instruction_en":"Which ending is right? The two choices are shown above each sentence. Type the right ending.","items":[{"label":"1","lead":"statt mich weiter über die Arbeit zu ärgern / statt mich nicht weiter über die Arbeit zu ärgern","text":"Ich wechsle den Job, ___.","gaps":[["statt mich weiter über die Arbeit zu ärgern"]],"solution":"Ich wechsle den Job, **statt mich weiter über die Arbeit zu ärgern**.","en":"I'm changing jobs instead of continuing to get annoyed about work.","why":"No *nicht* after *statt*: *statt* already says \"not this\".","source":"komma"},{"label":"2","lead":"ohne den Chef nicht zu informieren / ohne den Chef zu informieren","text":"Ich suche eine neue Stelle, ___.","gaps":[["ohne den Chef zu informieren"]],"solution":"Ich suche eine neue Stelle, **ohne den Chef zu informieren**.","en":"I'm looking for a new job without telling my boss.","why":"No *nicht* after *ohne*: *ohne den Chef nicht zu informieren* would mean the opposite.","source":"komma"}]},{"no":"16","tag":"C1","instruction":"Homeoffice. Ergänzen Sie die Sätze mit *statt … zu*.","instruction_en":"Working from home. Turn the second part (the thing you don't do) into *statt … zu* + infinitive. Leave out *nicht / keine*.","example":[{"label":"a","lead":"Sie können bei der Arbeit eine bequeme Sporthose tragen und müssen keine unbequeme Berufskleidung anziehen.","text":"Sie können bei der Arbeit eine bequeme Sporthose tragen, **statt unbequeme Berufskleidung anzuziehen**."}],"items":[{"label":"b","lead":"Sie haben flexible Arbeitszeiten und arbeiten nicht von 9 bis 17 Uhr.","text":"Sie haben flexible Arbeitszeiten, ___.","gaps":[["statt von 9 bis 17 Uhr zu arbeiten"]],"solution":"Sie haben flexible Arbeitszeiten, **statt von 9 bis 17 Uhr zu arbeiten**.","en":"You have flexible working hours instead of working from 9 to 5.","why":"*nicht* disappears; *zu arbeiten* goes last.","source":"komma"},{"label":"c","lead":"Sie haben keine Fahrtkosten und geben nicht viel Geld für Benzin aus.","text":"Sie haben keine Fahrtkosten, ___.","gaps":[["statt viel Geld für Benzin auszugeben"]],"solution":"Sie haben keine Fahrtkosten, **statt viel Geld für Benzin auszugeben**.","en":"You have no travel costs instead of spending a lot of money on petrol.","why":"*ausgeben* is separable: *aus**zu**geben*.","source":"komma"},{"label":"d","lead":"Sie räumen die Wohnung auf und arbeiten nicht.","text":"Sie räumen die Wohnung auf, ___.","gaps":[["statt zu arbeiten"]],"solution":"Sie räumen die Wohnung auf, **statt zu arbeiten**.","en":"You tidy up the flat instead of working.","why":"Nothing else belongs to *arbeiten*, so the group is just *statt zu arbeiten*.","source":"komma"},{"label":"e","lead":"Sie müssen viele Probleme allein lösen und besprechen sie nicht mit Kollegen.","text":"Sie müssen viele Probleme allein lösen, ___.","gaps":[["statt sie mit Kollegen zu besprechen"]],"solution":"Sie müssen viele Probleme allein lösen, **statt sie mit Kollegen zu besprechen**.","en":"You have to solve a lot of problems alone instead of discussing them with colleagues.","why":"*sie* = the problems; it stays inside the group.","source":"komma"}]},{"no":"17","tag":"C2","instruction":"Meine fleissige Arbeitskollegin Olga. Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"My hard-working colleague Olga. Join the two sentences. Something she does *instead of* something else → *statt … zu*. Something that doesn't happen *at the same time* → *ohne … zu*. Drop *nicht / kein*.","example":[{"label":"a","lead":"Sie steht jeden Tag um fünf Uhr auf. Sie beschwert sich nicht.","text":"Sie steht jeden Tag um fünf Uhr auf, **ohne sich zu beschweren**."}],"items":[{"label":"b","lead":"Sie kommt schon um 7 Uhr ins Büro. Sie fängt nicht erst um 9 Uhr an.","text":"","accept":["Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen."],"solution":"**Sie kommt schon um 7 Uhr ins Büro, statt erst um 9 Uhr anzufangen.**","en":"She comes into the office at 7 instead of only starting at 9.","why":"7 o'clock replaces 9 o'clock → *statt*. *anfangen*: *an**zu**fangen*.","source":"komma"},{"label":"c","lead":"Sie fährt immer mit dem Velo zur Arbeit. Sie nimmt nicht das Auto.","text":"","accept":["Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen."],"solution":"**Sie fährt immer mit dem Velo zur Arbeit, statt das Auto zu nehmen.**","en":"She always cycles to work instead of taking the car.","why":"The bike replaces the car → *statt*. (*das Velo* = Swiss for bicycle.)","source":"komma"},{"label":"d","lead":"Sie geht in der Mittagszeit joggen. Sie isst nicht.","text":"","accept":["Sie geht in der Mittagszeit joggen, statt etwas zu essen.","Sie geht in der Mittagszeit joggen, statt zu essen.","Sie geht in der Mittagszeit joggen, ohne etwas zu essen.","Sie geht in der Mittagszeit joggen, ohne zu essen."],"solution":"**Sie geht in der Mittagszeit joggen, statt etwas zu essen.**","en":"She goes jogging at lunchtime instead of eating.","why":"Jogging replaces lunch → *statt*.","source":"komma","check":"The official key has *statt etwas zu essen*. *ohne etwas zu essen* (she jogs and eats nothing) is also correct German and nearly the same here."},{"label":"e","lead":"Sie arbeitet viele Stunden am Stück. Sie macht keine Pause.","text":"","accept":["Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.","Sie arbeitet viele Stunden am Stück, ohne Pause zu machen."],"solution":"**Sie arbeitet viele Stunden am Stück, ohne eine Pause zu machen.**","en":"She works for hours on end without taking a break.","why":"A break doesn't happen while she works → *ohne*. *keine Pause* becomes *eine Pause*.","source":"komma"},{"label":"f","lead":"Sie sollte sich mehr um sich selbst kümmern. Sie arbeitet so viel.","text":"","accept":["Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten."],"solution":"**Sie sollte sich mehr um sich selbst kümmern, statt so viel zu arbeiten.**","en":"She should take more care of herself instead of working so much.","why":"Taking care of herself should replace working so much → *statt*.","source":"komma"}]}]},{"page":"AB 156","heading":"C  Etwas tun, statt nur zu träumen","heading_en":"Doing something instead of just dreaming","exercises":[{"no":"18","tag":"C2","marker":"◇","instruction":"Morgengewohnheiten. Was ist richtig? Kreuzen Sie an.","instruction_en":"Morning habits. Type *ohne* or *statt*. *statt* = instead of (one thing replaces another); *ohne* = without (something doesn't happen at the same time).","example":[{"label":"a","text":"Ich fahre zu jeder Jahreszeit mit dem Velo zur Arbeit, **statt** das Auto zu nehmen."}],"items":[{"label":"b","text":"Ich dusche am Morgen immer kalt, ___ warm zu baden.","gaps":[["statt"]],"solution":"Ich dusche am Morgen immer kalt, **statt** warm zu baden.","en":"I always have a cold shower in the morning instead of a warm bath.","why":"A cold shower replaces a warm bath.","source":"komma"},{"label":"c","text":"Ich trinke nie Kaffee, ___ Zeitung zu lesen.","gaps":[["ohne"]],"solution":"Ich trinke nie Kaffee, **ohne** Zeitung zu lesen.","en":"I never drink coffee without reading the paper.","why":"*nie … ohne* = every time I drink coffee, I read the paper.","source":"komma"},{"label":"d","text":"Ich gehe nie aus dem Haus, ___ meinen Regenschirm mitzunehmen.","gaps":[["ohne"]],"solution":"Ich gehe nie aus dem Haus, **ohne** meinen Regenschirm mitzunehmen.","en":"I never leave the house without taking my umbrella.","why":"*nie … ohne* = I always take it.","source":"komma"},{"label":"e","text":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, ___ sofort aufzustehen.","gaps":[["statt"]],"solution":"Ich bleibe morgens nach dem Aufwachen immer noch eine halbe Stunde liegen, **statt** sofort aufzustehen.","en":"In the morning after waking up I always stay in bed for another half hour instead of getting up straight away.","why":"Staying in bed replaces getting up.","source":"komma"}]},{"no":"19","tag":"C2","marker":"◆","instruction":"Was würden Sie in Ihrem Leben gern machen? Schreiben Sie Sätze mit *ohne … zu* und *statt … zu*.","instruction_en":"What would you like to do in your life? Combine a wish from the left part of the box with something from the right part, using *ohne … zu* or *statt … zu*. The crossed-out words are used in the example. The model answer is one possibility.","box":["beruflich selbstständig sein","mehr Geld verdienen","kaputte Sachen reparieren","eine Wohnung kaufen","mit meiner Familie in der Heimat telefonieren","gut Deutsch sprechen","mit dem Velo fahren","mit meiner Familie zusammenwohnen","…","viele Sprachkurse machen","immer zu Fuss gehen","allein leben","viel Geld ausgeben","sie in den Abfall werfen","Heimweh haben","jeden Franken sparen müssen","ein finanzielles Risiko eingehen","…"],"box_used":[0,16],"example":[{"label":"Beispiel","text":"Ich wäre gern beruflich selbstständig, **ohne ein finanzielles Risiko einzugehen**. Ich würde gern …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich würde gern mehr Geld verdienen, statt jeden Franken sparen zu müssen. Ich würde gern kaputte Sachen reparieren, statt sie in den Abfall zu werfen. Ich würde gern mit meiner Familie in der Heimat telefonieren, ohne Heimweh zu haben. Ich würde gern mit dem Velo fahren, statt immer zu Fuss zu gehen. Ich würde gern gut Deutsch sprechen, ohne viele Sprachkurse zu machen. Ich würde gern mit meiner Familie zusammenwohnen, statt allein zu leben.","en":"I'd like to earn more money instead of having to save every franc. I'd like to repair broken things instead of throwing them away. I'd like to phone my family back home without feeling homesick. I'd like to cycle instead of always walking. I'd like to speak good German without doing lots of language courses. I'd like to live with my family instead of living alone.","why":"Wish with *würde gern* / *wäre gern*, then *statt … zu* (replacement) or *ohne … zu* (it doesn't happen). With a modal: *sparen **zu müssen***.","source":"hueber"}]},{"no":"20","tag":"C3","instruction":"Unglücklich im neuen Job – Ratschläge für eine Freundin","instruction_en":"Unhappy in a new job: advice for a friend","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Complete the advice with the phrases from the box. Each one is used once; *Wie wäre es, wenn* is used in the example.","box":["An deiner Stelle","Du könntest zum Beispiel","Ich kann dir nur raten","Wie wäre es, wenn","Wie findest du die Idee","solltest du vielleicht"],"box_used":[3],"box_exact":true,"example":[{"label":"1","text":"**Wie wäre es, wenn** du mit deinen Kollegen zusammen Mittagspause machen würdest, statt allein zu essen?"}],"items":[{"label":"2","text":"Wenn du Kollegen besser kennenlernen möchtest, ___ öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","gaps":[["solltest du vielleicht"]],"solution":"Wenn du Kollegen besser kennenlernen möchtest, **solltest du vielleicht** öfters am Tag kurz in die Kaffeeküche gehen. Da kannst du dich entspannt mit allen unterhalten, ohne sie bei der Arbeit zu stören.","en":"If you'd like to get to know your colleagues better, maybe you should pop into the coffee kitchen more often during the day. There you can chat to everyone in a relaxed way without disturbing them at work.","why":"After the *wenn*-clause the verb comes first: *…, solltest du vielleicht …*; *gehen* goes to the end.","source":"hueber"},{"label":"3","text":"___, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","gaps":[["Wie findest du die Idee"]],"solution":"**Wie findest du die Idee**, an einem Tag für die Kollegen in deiner Abteilung Kuchen mitzubringen und deinen ersten Monat in der neuen Firma zu feiern? Über einen Kuchen freuen sich alle.","en":"How about the idea of bringing in cake for the colleagues in your department one day and celebrating your first month at the new company? Everyone loves cake.","why":"*Wie findest du die Idee, … zu …?* is a question with *zu* + infinitive.","source":"g6865"},{"label":"4","text":"___ würde ich überallhin gehen, wo man Kollegen treffen kann. ___ am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","gaps":[["An deiner Stelle"],["Du könntest zum Beispiel"]],"solution":"**An deiner Stelle** würde ich überallhin gehen, wo man Kollegen treffen kann. **Du könntest zum Beispiel** am Firmensportprogramm teilnehmen. Da lernst du dann auch Leute aus anderen Abteilungen kennen.","en":"If I were you, I'd go anywhere you can meet colleagues. You could, for example, take part in the company sports programme. Then you'll also get to know people from other departments.","why":"*An deiner Stelle würde ich …* (if I were you); *Du könntest zum Beispiel …* + infinitive at the end.","source":"hueber"},{"label":"5","text":"___, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","gaps":[["Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten**, offen zu sein und positiv zu denken. Du wirst sehen, in ein paar Wochen wird es dir schon besser gehen.","en":"I can only advise you to be open and think positively. You'll see, in a few weeks you'll already feel better.","why":"*Ich kann dir nur raten, … zu …*: the advice comes as *zu* + infinitive.","source":"g6865"}]},{"no":"20","part":"b","part_instruction":"Schreiben Sie zwei weitere Ratschläge.","part_instruction_en":"Write two more pieces of advice for the friend. The model answer is one possibility.","example":[{"label":"Beispiel","text":"Ich kann dir nur raten, …"}],"items":[{"label":"1","lead":"Ihre Ratschläge","text":"","open":true,"solution":"Ich kann dir nur raten, mit deiner Chefin zu sprechen. Wie findest du die Idee, dich nach der Arbeit mit deinen Kollegen zu verabreden?","en":"I can only advise you to talk to your boss. What do you think of the idea of meeting up with your colleagues after work?","why":"Both phrases take *zu* + infinitive at the end; with a reflexive verb the pronoun stays inside: *dich … zu verabreden*.","source":"g6865"}]}]},{"page":"AB 157","heading":"D  Verkaufsgespräche","heading_en":"Sales conversations","exercises":[{"no":"21","tag":"D3","instruction":"Ich hätte gern …","instruction_en":"I'd like …","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie: Kundin (K), Verkäuferin (V).","part_instruction_en":"Who says what? Type *K* for the customer (*Kundin*) or *V* for the shop assistant (*Verkäuferin*).","example":[{"label":"4 / c","text":"Vielen Dank für Ihre Hilfe. → **K** / Vielen Dank für Ihre Beratung. → **K**"}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … empfehlen? → **V**","en":"May I recommend … to you? → shop assistant","why":"Recommending is the seller's job.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["K","Kundin"]],"solution":"Das muss ich mir noch überlegen. → **K**","en":"I need to think about it. → customer","why":"The customer hasn't decided yet.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["V","Verkäuferin"]],"solution":"Brauchen Sie Hilfe? → **V**","en":"Do you need help? → shop assistant","why":"Offering help.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["V","Verkäuferin"]],"solution":"Was wünschen Sie? → **V**","en":"What would you like? → shop assistant","why":"The seller asks what you want.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["K","Kundin"]],"solution":"Entschuldigung, ist es möglich, …? → **K**","en":"Excuse me, is it possible to …? → customer","why":"The customer asks for something.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie noch einen Wunsch? → **V**","en":"Is there anything else? → shop assistant","why":"Asked near the end of a sale.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["K","Kundin"]],"solution":"Ich bin auf der Suche nach … → **K**","en":"I'm looking for … → customer","why":"The customer says what they need.","source":"hueber"},{"label":"a","text":"Ich hätte gern … → ___","gaps":[["K","Kundin"]],"solution":"Ich hätte gern … → **K**","en":"I'd like … → customer","why":"Polite way to ask for something (Konjunktiv II).","source":"hueber"},{"label":"b","text":"Wie kann ich Ihnen helfen? → ___","gaps":[["V","Verkäuferin"]],"solution":"Wie kann ich Ihnen helfen? → **V**","en":"How can I help you? → shop assistant","why":"Offering help.","source":"hueber"},{"label":"d","text":"Haben Sie einen bestimmten Wunsch? → ___","gaps":[["V","Verkäuferin"]],"solution":"Haben Sie einen bestimmten Wunsch? → **V**","en":"Are you looking for anything in particular? → shop assistant","why":"The seller asks what you want.","source":"hueber"},{"label":"e","text":"Darf ich Ihnen … anbieten? → ___","gaps":[["V","Verkäuferin"]],"solution":"Darf ich Ihnen … anbieten? → **V**","en":"May I offer you …? → shop assistant","why":"Offering something.","source":"hueber"},{"label":"f","text":"Ich kann mich noch nicht entscheiden. → ___","gaps":[["K","Kundin"]],"solution":"Ich kann mich noch nicht entscheiden. → **K**","en":"I can't decide yet. → customer","why":"The customer hasn't decided.","source":"hueber"},{"label":"g","text":"Dürfte ich Sie etwas fragen? Kann man … → ___","gaps":[["K","Kundin"]],"solution":"Dürfte ich Sie etwas fragen? Kann man … → **K**","en":"Could I ask you something? Can you …? → customer","why":"Polite question (Konjunktiv II *dürfte*).","source":"hueber"},{"label":"h","text":"Möchten Sie sonst noch etwas? → ___","gaps":[["V","Verkäuferin"]],"solution":"Möchten Sie sonst noch etwas? → **V**","en":"Would you like anything else? → shop assistant","why":"Asked near the end of a sale.","source":"hueber"}]},{"no":"21","part":"b","part_instruction":"Wie kann man auch sagen? Verbinden Sie die Sätze in a.","part_instruction_en":"Which sentence on the right (a–h) means the same as each sentence on the left? Type the letter.","phrases":["a Ich hätte gern …","b Wie kann ich Ihnen helfen?","c Vielen Dank für Ihre Beratung.","d Haben Sie einen bestimmten Wunsch?","e Darf ich Ihnen … anbieten?","f Ich kann mich noch nicht entscheiden.","g Dürfte ich Sie etwas fragen? Kann man …","h Möchten Sie sonst noch etwas?"],"example":[{"label":"4","text":"Vielen Dank für Ihre Hilfe. → **c** Vielen Dank für Ihre Beratung."}],"items":[{"label":"1","text":"Darf ich Ihnen … empfehlen? → ___","gaps":[["e"]],"solution":"Darf ich Ihnen … empfehlen? → **e**","en":"May I recommend …? → e May I offer you …?","why":"Both suggest something to the customer.","source":"hueber"},{"label":"2","text":"Das muss ich mir noch überlegen. → ___","gaps":[["f"]],"solution":"Das muss ich mir noch überlegen. → **f**","en":"I need to think about it. → f I can't decide yet.","why":"Both say: not decided yet.","source":"hueber"},{"label":"3","text":"Brauchen Sie Hilfe? → ___","gaps":[["b"]],"solution":"Brauchen Sie Hilfe? → **b**","en":"Do you need help? → b How can I help you?","why":"Both offer help.","source":"hueber"},{"label":"5","text":"Was wünschen Sie? → ___","gaps":[["d"]],"solution":"Was wünschen Sie? → **d**","en":"What would you like? → d Are you looking for anything in particular?","why":"Both ask what the customer wants.","source":"hueber"},{"label":"6","text":"Entschuldigung, ist es möglich, …? → ___","gaps":[["g"]],"solution":"Entschuldigung, ist es möglich, …? → **g**","en":"Excuse me, is it possible to …? → g Could I ask you something? Can you …?","why":"Both are polite questions from the customer.","source":"hueber"},{"label":"7","text":"Haben Sie noch einen Wunsch? → ___","gaps":[["h"]],"solution":"Haben Sie noch einen Wunsch? → **h**","en":"Is there anything else? → h Would you like anything else?","why":"Both ask if the customer wants more.","source":"hueber"},{"label":"8","text":"Ich bin auf der Suche nach … → ___","gaps":[["a"]],"solution":"Ich bin auf der Suche nach … → **a**","en":"I'm looking for … → a I'd like …","why":"Both say what the customer wants.","source":"hueber"}]}]},{"page":"AB 158","heading":"E  Reklamation","heading_en":"Complaints","exercises":[{"no":"23","tag":"E2","instruction":"Ergänzen Sie.","instruction_en":"Complete the sentences from complaint letters. The book gives some letters of each word (shown above the sentence); type the whole word. (Exercise 22 is a listening task and is left out.)","items":[{"label":"a","lead":"f _ _ _ _ _ _  …  _ _ _","text":"Ich ___ Sie jetzt zum letzten Mal ___, mir bis 31.03. zu antworten.","gaps":[["fordere"],["auf"]],"solution":"Ich **fordere** Sie jetzt zum letzten Mal **auf**, mir bis 31.03. zu antworten.","en":"I am asking you for the last time to reply to me by 31 March.","why":"*jemanden auffordern, … zu …* = to call on / demand that someone …; separable: *ich fordere … auf*.","source":"hueber"},{"label":"b","lead":"S _ _ _ _ _ _ _  /  E _ _ _ _ _  /  A _ s p _ _ _ _","text":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. ___ Sie mir bitte einen ___. Ich habe ___ auf eine neue Uhr.","gaps":[["Schicken"],["Ersatz"],["Anspruch"]],"solution":"Leider funktioniert die Uhr, die ich gestern gekauft habe, nicht. **Schicken** Sie mir bitte einen **Ersatz**. Ich habe **Anspruch** auf eine neue Uhr.","en":"Unfortunately the watch I bought yesterday doesn't work. Please send me a replacement. I am entitled to a new watch.","why":"*der Ersatz* = replacement; *Anspruch haben auf* + accusative = to be entitled to.","source":"hueber"},{"label":"c","lead":"b _ _ _ _ ä _ _ _ t","text":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … ___ ist.","gaps":[["beschädigt"]],"solution":"Als ich das Paket geöffnet habe, habe ich leider festgestellt, dass der/die … **beschädigt** ist.","en":"When I opened the parcel, I unfortunately found that the … is damaged.","why":"*beschädigt* = damaged.","source":"hueber"},{"label":"d","lead":"ä _ g _ _ l _ _ _","text":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr ___.","gaps":[["ärgerlich"]],"solution":"Ich habe Ihnen jetzt schon zweimal geschrieben, ohne eine Antwort zu erhalten. Das ist wirklich sehr **ärgerlich**.","en":"I've written to you twice now without getting a reply. That is really very annoying.","why":"*ärgerlich* = annoying.","source":"hueber"},{"label":"e","lead":"u _ _ a _ _ _ _ _ _","text":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser ___.","gaps":[["umtauschen"]],"solution":"Der Pullover ist schön, jedoch passt er meinem Mann leider nicht. Ich möchte ihn daher gern in eine Nummer grösser **umtauschen**.","en":"The jumper is nice, but unfortunately it doesn't fit my husband. So I'd like to exchange it for a size bigger.","why":"*umtauschen* = to exchange (in a shop).","source":"hueber"},{"label":"f","lead":"A _ _ _ o _ _","text":"Leider habe ich immer noch keine ___ erhalten.","gaps":[["Antwort"]],"solution":"Leider habe ich immer noch keine **Antwort** erhalten.","en":"Unfortunately I still haven't received a reply.","why":"*die Antwort* = reply.","source":"hueber"},{"label":"g","lead":"B _ _ t _ _ _ _ e _","text":"___ Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","gaps":[["Bestätigen"]],"solution":"**Bestätigen** Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben.","en":"Please confirm to me in writing that you have received my complaint.","why":"*bestätigen* = to confirm.","source":"hueber"},{"label":"h","lead":"v _ _ ä _ _ _ r _  /  e _ _ t _ _ _ _ _ _","text":"Ich bin sehr ___ und von Ihrem Service sehr ___.","gaps":[["verärgert"],["enttäuscht"]],"solution":"Ich bin sehr **verärgert** und von Ihrem Service sehr **enttäuscht**.","en":"I am very annoyed and very disappointed with your service.","why":"*verärgert* = annoyed; *enttäuscht von* = disappointed with.","source":"hueber"}]},{"no":"24","tag":"E2","instruction":"Eine schriftliche Reklamation","instruction_en":"A written complaint","part":"a","part_instruction":"Was bedeuten die Sätze? Ordnen Sie zu.","part_instruction_en":"The left sentences are how you write in a complaint letter; the box shows how you would say it in everyday speech. Type the letter (a–g) with the same meaning.","phrases":["a Wenn ich bis … nichts gehört habe, dann will ich den/die … nicht mehr haben.","b Ich habe Ihnen schon zweimal geschrieben und gesagt, dass ich eine(n) neue(n) … möchte.","c Schade. Der/Die … ist kaputt.","d Ich sage es Ihnen jetzt noch ein letztes Mal: Bitte schicken Sie mir spätestens am … eine(n) neue(n) …","e Ich habe wirklich gedacht, dass Ihr Service viel besser ist.","f Ich bin enttäuscht, dass ich immer noch nichts von Ihnen gehört habe.","g Ich habe am 16. Februar von Ihnen … bekommen."],"example":[{"label":"2","text":"Leider ist … defekt. → **c** Schade. Der/Die … ist kaputt."}],"items":[{"label":"1","text":"Am 16.2. haben Sie mir … geliefert. → ___","gaps":[["g"]],"solution":"Am 16.2. haben Sie mir … geliefert. → **g**","en":"On 16 Feb you delivered … to me. → g","why":"Both say what you received and when.","source":"hueber"},{"label":"3","text":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → ___","gaps":[["b"]],"solution":"Ich habe Ihnen bereits zweimal ein E-Mail geschrieben und Sie gebeten, mir einen Ersatz zu schicken. → **b**","en":"I have already sent you two e-mails asking you to send me a replacement. → b","why":"*bereits* = *schon*; *Ersatz* = a new one. (*das E-Mail* is Swiss usage.)","source":"hueber"},{"label":"4","text":"Leider habe ich immer noch keine Antwort erhalten. → ___","gaps":[["f"]],"solution":"Leider habe ich immer noch keine Antwort erhalten. → **f**","en":"Unfortunately I still haven't received a reply. → f","why":"No reply yet → disappointed.","source":"hueber"},{"label":"5","text":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → ___","gaps":[["e"]],"solution":"Ich muss sagen, Ihr Service hat mich sehr enttäuscht. → **e**","en":"I have to say your service has disappointed me a lot. → e","why":"You expected better service.","source":"hueber"},{"label":"6","text":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → ___","gaps":[["d"]],"solution":"Ich fordere Sie zum letzten Mal auf, mir bis … einen Ersatz zu schicken. → **d**","en":"I am asking you for the last time to send me a replacement by … → d","why":"*zum letzten Mal* = *ein letztes Mal*.","source":"hueber"},{"label":"7","text":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → ___","gaps":[["a"]],"solution":"Wenn ich bis … nichts von Ihnen höre, dann verzichte ich auf die Bestellung. → **a**","en":"If I don't hear from you by …, I'll cancel the order. → a","why":"*auf etwas verzichten* = to do without / give up something.","source":"hueber"}]},{"no":"24","tag":"Schreibtraining","part":"b","part_instruction":"Wählen Sie eine Situation und schreiben Sie eine Reklamation wie in a. Die Sätze 1–7 helfen Ihnen.","part_instruction_en":"Choose a situation and write a complaint as in a. The sentences 1–7 help you. The model answers are one possibility each.","reading":[{"label":"1","text":"Kopfhörer bestellt – funktioniert nicht – schon einmal geschrieben, aber keine Antwort erhalten – bitte Ersatz bis … senden – wenn wieder keine Antwort, auf Bestellung verzichten"},{"label":"2","text":"Laptoptasche bestellt – Trageriemen nach einer Woche gerissen – zurückschicken – umtauschen oder Ersatz – bitte Reklamation bestätigen"}],"example":[{"label":"Beispiel","text":"Sehr geehrte Damen und Herren / Am 12.3. … / Freundliche Grüsse"}],"items":[{"label":"1","lead":"Situation 1: Kopfhörer","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 12.3. haben Sie mir Kopfhörer geliefert. Leider funktionieren sie nicht. Ich habe Ihnen schon einmal geschrieben, aber keine Antwort erhalten. Ich fordere Sie zum letzten Mal auf, mir bis 12.4. einen Ersatz zu schicken. Wenn ich wieder keine Antwort von Ihnen erhalte, dann verzichte ich auf die Bestellung. / Freundliche Grüsse / Luca Carelli","en":"Dear Sir or Madam / On 12 March you delivered headphones to me. Unfortunately they don't work. I have already written to you once but received no reply. I am asking you for the last time to send me a replacement by 12 April. If I again receive no reply from you, I will cancel the order. / Kind regards / Luca Carelli","why":"The key points in order: what you got and when, what is wrong, what you did, what the firm must do (*auffordern, … zu …*), what you will do otherwise.","source":"hueber"},{"label":"2","lead":"Situation 2: Laptoptasche","text":"","open":true,"solution":"Sehr geehrte Damen und Herren / Am 3.5. haben Sie mir eine Laptoptasche geliefert. Leider ist der Trageriemen schon nach einer Woche gerissen. Das ist sehr ärgerlich. Ich schicke Ihnen die Tasche heute zurück und bitte Sie, sie umzutauschen oder mir einen Ersatz zu schicken. Im Anhang finden Sie eine Kopie der Rechnung. Bestätigen Sie mir bitte schriftlich, dass Sie meine Reklamation erhalten haben. / Freundliche Grüsse / Maria Keller","en":"Dear Sir or Madam / On 3 May you delivered a laptop bag to me. Unfortunately the shoulder strap tore after only one week. That is very annoying. I am sending the bag back to you today and ask you to exchange it or send me a replacement. Attached is a copy of the invoice. Please confirm in writing that you have received my complaint. / Kind regards / Maria Keller","why":"Our own model (the key has none for situation 2). *bitten, … zu …*: *umzutauschen* (separable).","source":"g6865"}]}]},{"page":"AB 159","heading":"Test Lektion 6","heading_en":"Lesson 6 test","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Complete the text. The book gives some letters of each word (shown above the sentence); type the whole word.","example":[{"label":"a","text":"Ich war **jahrelang** angestellt, …"}],"items":[{"label":"b","lead":"b: e _ t _ _ _ _ l _ s _ _ n  /  c: K _ _ _ _ a _ _","text":"… aber irgendwann war ich unzufrieden und habe mich ___: Ich mache mich als ___ selbstständig und gründe eine Firma.","gaps":[["entschlossen"],["Kaufmann","Kauffrau"]],"solution":"… aber irgendwann war ich unzufrieden und habe mich **entschlossen**: Ich mache mich als **Kaufmann** selbstständig und gründe eine Firma.","en":"… but at some point I was unhappy and made up my mind: I am setting up on my own as a businessman and founding a company.","why":"*sich entschliessen* (Perfekt: *hat sich entschlossen*) = to decide. *der Kaufmann* = businessman, merchant.","source":"g6865","check":"The letters given point to *Kaufmann*; a woman would write *Kauffrau*, which has a different pattern. Both are accepted. The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"d","lead":"G _ _ _ _ ä _ _ _ l _ _ _ e","text":"Ein paar Freunde, die gute ___ sind, helfen mir dabei.","gaps":[["Geschäftsleute"]],"solution":"Ein paar Freunde, die gute **Geschäftsleute** sind, helfen mir dabei.","en":"A few friends who are good business people are helping me with it.","why":"*die Geschäftsleute* = business people (plural).","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"e","lead":"e: f _ _ _ _ z _ _ _ _ _ s  /  f: l _ _ _ t","text":"Ich glaube nicht, dass es ein ___ Risiko ist. Im Gegenteil, ich denke es ___ sich.","gaps":[["finanzielles"],["lohnt"]],"solution":"Ich glaube nicht, dass es ein **finanzielles** Risiko ist. Im Gegenteil, ich denke es **lohnt** sich.","en":"I don't think it's a financial risk. On the contrary, I think it's worth it.","why":"*ein finanzielles Risiko* (neuter); *es lohnt sich* = it's worth it.","source":"platzhalter","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit *damit* oder – wenn möglich – *um … zu*.","instruction_en":"Join the two sentences. Use *um … zu* when the person is the same; otherwise use *damit*.","example":[{"label":"a","lead":"Erika lernt Englisch. Sie möchte ausländische Kunden besser verstehen.","text":"Erika lernt Englisch, **um ausländische Kunden besser zu verstehen**."}],"items":[{"label":"b","lead":"Tomás macht eine Weiterbildung. Er möchte seine kommunikativen Kompetenzen verbessern.","text":"","accept":["Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern."],"solution":"**Tomás macht eine Weiterbildung, um seine kommunikativen Kompetenzen zu verbessern.**","en":"Tomás is doing a training course to improve his communication skills.","why":"Same person (Tomás) → *um … zu*; *möchte* is dropped.","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"c","lead":"Frau Seil arbeitet nur halbtags. Die Kinder sollen nicht allein sein, wenn sie aus der Schule kommen.","text":"","accept":["Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen."],"solution":"**Frau Seil arbeitet nur halbtags, damit die Kinder nicht allein sind, wenn sie aus der Schule kommen.**","en":"Ms Seil only works half-days so that the children aren't alone when they come home from school.","why":"Other person (the children) → *damit*; *sollen* is dropped.","source":"damit","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"d","lead":"Rodolfo kümmert sich diese Woche um die Kinder. Seine Frau kann ihre kranke Mutter besuchen.","text":"","accept":["Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann."],"solution":"**Rodolfo kümmert sich diese Woche um die Kinder, damit seine Frau ihre kranke Mutter besuchen kann.**","en":"Rodolfo is looking after the children this week so that his wife can visit her sick mother.","why":"Other person (his wife) → *damit*; *kann* goes last.","source":"damit","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."}]},{"no":"3","instruction":"Ergänzen Sie: *ohne … zu* oder *statt … zu*.","instruction_en":"Type *ohne* or *statt* in the first gap and *zu* in the second.","example":[{"label":"a","text":"Wenn man streiten kann, **ohne** alles persönlich **zu** nehmen, dann ist man konfliktfähig."}],"items":[{"label":"b","text":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, ___ ergebnislos ___ streiten.","gaps":[["statt"],["zu"]],"solution":"Man ist kompromissfähig, wenn man sich in Streitfragen mit jemandem einigt, **statt** ergebnislos **zu** streiten.","en":"You are good at compromise if you reach agreement with someone in a dispute instead of arguing without result.","why":"Agreeing replaces arguing → *statt*.","source":"komma","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"c","text":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, ___ sich selbst zu wichtig ___ nehmen.","gaps":[["ohne"],["zu"]],"solution":"Ein guter Chef ist jemand, der seine Mitarbeiter führt, **ohne** sich selbst zu wichtig **zu** nehmen.","en":"A good boss is someone who leads their staff without taking themselves too seriously.","why":"He leads and at the same time doesn't take himself too seriously → *ohne*. The first *zu* means \"too\".","source":"komma","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"d","text":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, ___ immer nur alles allein ___ machen.","gaps":[["statt"],["zu"]],"solution":"Wer teamfähig ist, arbeitet gern mit Kollegen zusammen, **statt** immer nur alles allein **zu** machen.","en":"Anyone who is a good team player likes working with colleagues instead of always doing everything alone.","why":"Teamwork replaces working alone → *statt*.","source":"komma","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"e","text":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, ___ gestresst ___ sein.","gaps":[["ohne"],["zu"]],"solution":"Flexibel ist jemand, der sich schnell und ohne Probleme an neue Situationen gewöhnen kann, **ohne** gestresst **zu** sein.","en":"Flexible means someone who can get used to new situations quickly and without problems, without being stressed.","why":"Stress doesn't happen → *ohne*.","source":"komma","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."}]},{"no":"4","instruction":"Vor dem Bewerbungsgespräch. Was ist richtig? Kreuzen Sie an.","instruction_en":"Before the job interview: advice for a friend. Type the phrase that fits the rest of the sentence. The two choices are shown above each sentence.","example":[{"label":"a","text":"**An deiner Stelle würde** ich heute noch ein bisschen über die Firma im Internet recherchieren."}],"items":[{"label":"b","lead":"Wie wäre es, wenn / Ich kann dir nur raten,","text":"___ du dir ein paar Fragen überlegst, die du morgen stellen kannst?","gaps":[["Wie wäre es, wenn","Wie wäre es wenn"]],"solution":"**Wie wäre es, wenn** du dir ein paar Fragen überlegst, die du morgen stellen kannst?","en":"How about thinking of a few questions you can ask tomorrow?","why":"*du … überlegst* with the verb at the end needs *wenn*: *Wie wäre es, wenn …?*","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"c","lead":"Was hältst du davon, / Du könntest zum Beispiel","text":"___ fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","gaps":[["Du könntest zum Beispiel"]],"solution":"**Du könntest zum Beispiel** fragen, wie gross das Team ist oder was deine Aufgaben sein werden.","en":"You could, for example, ask how big the team is or what your tasks will be.","why":"A bare infinitive (*fragen*) follows a modal verb: *Du könntest … fragen*.","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"d","lead":"An deiner Stelle würde ich / Ich kann dir nur raten,","text":"___ du selbst zu sein. Das ist das Allerwichtigste.","gaps":[["Ich kann dir nur raten,","Ich kann dir nur raten"]],"solution":"**Ich kann dir nur raten,** du selbst zu sein. Das ist das Allerwichtigste.","en":"I can only advise you to be yourself. That is the most important thing of all.","why":"*zu sein* needs a phrase that takes *zu* + infinitive: *Ich kann dir nur raten, …*","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."},{"label":"e","lead":"Wie wäre es, wenn / Was hältst du davon,","text":"___ heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","gaps":[["Was hältst du davon,","Was hältst du davon"]],"solution":"**Was hältst du davon,** heute Abend essen zu gehen? Das bringt dich auf andere Gedanken.","en":"What do you think about going out to eat tonight? That will take your mind off things.","why":"*essen zu gehen* (zu + infinitive) fits *Was hältst du davon, … zu …?*","source":"g6865","check":"The answer key for the Arbeitsbuch does not cover the lesson test; this answer is ours, checked against grammis."}]}]},{"page":"AB 160","heading":"Fokus Beruf: Kundenwünsche","heading_en":"Focus on work: customer requests","exercises":[{"no":"3","instruction":"Arbeiten Sie zu dritt. Wählen Sie je eine Rolle und spielen Sie drei Telefongespräche.","instruction_en":"Work in threes: each person takes a role and you act out three phone calls. Practise by writing or saying them; the model dialogues are one possibility. (Exercises 1 and 2 are listening tasks and are left out.)","reading":[{"label":"A  Kundin/Kunde","text":"Sie machen heute eine Grillparty. Sie haben beim Getränkeservice *Getränkeblitz* drei Harasse Mineralwasser und vier Harasse Süssmost bestellt."},{"label":"B  Angestellte/Angestellter","text":"Sie arbeiten bei der Firma *Getränkeblitz* und bekommen einen Beschwerdeanruf von einer Kundin. Sie können nicht direkt helfen. Sie müssen zuerst mit dem Fahrer sprechen und rufen die Kundin dann zurück."},{"label":"C  Fahrerin/Fahrer","text":"Sie arbeiten als Fahrer/in für die Firma *Getränkeblitz*. Sie haben für die Grillparty sieben Harasse Mineralwasser geliefert."}],"phrases":["Gespräch 1 – Kunde: Ich habe bei Ihnen … bestellt. | Jetzt ist die Lieferung gekommen, aber … | Sie haben wohl einen Fehler gemacht. | Ich habe … bestellt und nicht …","Gespräch 1 – Angestellte: Oh, das tut mir leid. | Da ist wohl ein Fehler/ein Irrtum passiert. | Ich rufe sofort meine Kollegin/meinen Kollegen an. | Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","Gespräch 2 – Angestellte: Frau/Herr … hat angerufen. | Du hast ihm/ihr … statt … geliefert. | Wir machen Folgendes: … | Ich rufe an und frage nach, ob das okay ist.","Gespräch 2 – Fahrer: Oh je, da habe ich wohl einen Fehler gemacht. | Da habe ich wohl etwas verwechselt. | Was machen wir denn jetzt? | Ich könnte …","Gespräch 3 – Angestellte: Es tut mir wahnsinnig leid. | Meine Kollegin/Mein Kollege hat einen Fehler gemacht. | Wir könnten Ihnen … | Selbstverständlich geben wir Ihnen einen Rabatt.","Gespräch 3 – Kunde: Ja, damit bin ich einverstanden. | Nein, tut mir leid. Das war doch Ihr Fehler, nicht meiner. | Ich mache Ihnen einen anderen Vorschlag: …"],"items":[{"label":"1","lead":"Gespräch 1: Kundin und Angestellter","text":"","open":true,"solution":"Kundin: Grüezi, hier ist Meier. Ich habe bei Ihnen drei Harasse Mineralwasser und vier Harasse Süssmost bestellt. Jetzt ist die Lieferung gekommen, aber es sind sieben Harasse Mineralwasser. Ich habe Süssmost bestellt und nicht nur Wasser! / Angestellter: Oh, das tut mir leid. Da ist wohl ein Fehler passiert. Ich rufe sofort meinen Kollegen an. Bitte geben Sie mir Ihre Handynummer, ich rufe Sie sofort zurück.","en":"Customer: Hello, this is Meier. I ordered three crates of mineral water and four crates of apple juice from you. The delivery has just come, but it's seven crates of mineral water. I ordered apple juice, not just water! / Employee: Oh, I'm sorry. There must have been a mistake. I'll call my colleague right away. Please give me your mobile number and I'll call you straight back.","why":"Complaint: say what you ordered and what came (*bestellt … und nicht …*). The employee apologises and promises to call back. (*der Harass* = Swiss for crate; *der Süssmost* = Swiss apple juice.)","source":"hueber"},{"label":"2","lead":"Gespräch 2: Angestellter und Fahrer","text":"","open":true,"solution":"Angestellter: Hallo Marco, Frau Meier hat angerufen. Du hast ihr sieben Harasse Mineralwasser statt drei Harasse Wasser und vier Harasse Süssmost geliefert. / Fahrer: Oh je, da habe ich wohl etwas verwechselt. Was machen wir denn jetzt? Ich könnte heute Nachmittag noch einmal hinfahren. / Angestellter: Gut, wir machen Folgendes: Du bringst ihr vier Harasse Süssmost und holst vier Harasse Wasser wieder ab. Ich rufe an und frage nach, ob das okay ist.","en":"Employee: Hi Marco, Ms Meier called. You delivered seven crates of mineral water to her instead of three crates of water and four of apple juice. / Driver: Oh dear, I must have mixed something up. What do we do now? I could drive there again this afternoon. / Employee: OK, here's what we'll do: you take her four crates of apple juice and pick up four crates of water. I'll call and check if that's OK.","why":"Colleagues use *du*. *statt* + noun here (*statt drei Harasse Wasser*): the same idea as *statt … zu*, but with a thing.","source":"hueber"},{"label":"3","lead":"Gespräch 3: Angestellter und Kundin","text":"","open":true,"solution":"Angestellter: Frau Meier, es tut mir wahnsinnig leid. Mein Kollege hat einen Fehler gemacht. Wir könnten Ihnen den Süssmost noch heute bis 17 Uhr bringen. Selbstverständlich geben wir Ihnen einen Rabatt von 20 Prozent. / Kundin: Ja, damit bin ich einverstanden. Die Party fängt erst um 18 Uhr an. Vielen Dank!","en":"Employee: Ms Meier, I'm terribly sorry. My colleague made a mistake. We could bring you the apple juice today by 5 pm. Of course we'll give you a 20 per cent discount. / Customer: Yes, I'm happy with that. The party only starts at 6. Thank you very much!","why":"Offer a solution with *Wir könnten Ihnen …* (Konjunktiv II = polite). The customer accepts: *damit bin ich einverstanden* (here *damit* = with that, not *so that*).","source":"hueber"}]}]}],"sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (official answer key, Lektion 6)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (um … zu has no subject of its own; it is taken from the main clause)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"damit","title":"grammis connector dictionary: damit (subjunctor with the verb at the end; also an adverb meaning \"with that\")","url":"https://grammis.ids-mannheim.de/konnektoren/407001"},{"id":"komma","title":"grammis: Komma bei Nebensätzen (infinitive clauses with um, ohne, (an)statt are set off by a comma)","url":"https://grammis.ids-mannheim.de/rechtschreibung/6203"},{"id":"platzhalter","title":"grammis: Platzhalter (es in position 1; formal es with weather verbs stays: Heute schneit es)","url":"https://grammis.ids-mannheim.de/vggf/2284"},{"id":"korrelat","title":"grammis: Korrelat (es pointing forward to a clause: Ich kann es nicht erwarten, euch zu sehen)","url":"https://grammis.ids-mannheim.de/vggf/2283"}]}];
